"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1772],{84303:(e,a,i)=>{i.d(a,{NC:()=>l,NF:()=>d,WD:()=>r,lP:()=>s,wu:()=>o});let s=["markets","crypto","defi","macro"],t=[{id:"xau-dollar",category:"markets",ticker:"XAU/USD",tags:["XAU","GOLD","DXY","XAG","SILVER"],publishedAt:"2026-10-23",direction:"long",levels:{entry:2400,target:2520,invalidation:2340,unit:"USD"},risk:"elevated",thesisWeights:[60,40]},{id:"nvda-duration",category:"markets",ticker:"NVDA",tags:["NVDA","AI","TSM","AVGO","MSFT","HOOD","AMD"],publishedAt:"2026-10-23",direction:"long",levels:{entry:120,target:138,invalidation:111,unit:"USD"},risk:"high",thesisWeights:[55,45]},{id:"btc-liquidity",category:"crypto",ticker:"BTC/USD",tags:["BTC","BITCOIN","ETF","SMC","SOL"],publishedAt:"2026-10-23",direction:"long",levels:{entry:6e4,target:66e3,invalidation:57e3,unit:"USD"},risk:"high",thesisWeights:[55,45]},{id:"eth-rotation",category:"crypto",ticker:"ETH/USD",tags:["ETH","ETHEREUM","BTC","SOL","ETF","SMC"],publishedAt:"2026-10-23",direction:"long",levels:{entry:2500,target:2800,invalidation:2350,unit:"USD"},risk:"high",thesisWeights:[50,50]},{id:"defi-clmm",category:"defi",ticker:"DEFI",tags:["DEFI","CLMM","ETH","USDC","YIELD"],publishedAt:"2026-10-22",direction:"long",levels:{entry:100,target:103,invalidation:95,unit:"INDEX"},risk:"protocol",thesisWeights:[45,55]},{id:"stablecoin-custody",category:"defi",ticker:"USDT/DEFI",tags:["USDT","USDC","DEFI","CUSTODY","STABLECOIN"],publishedAt:"2026-10-22",direction:"long",levels:{entry:1,target:1.01,invalidation:.98,unit:"USD"},risk:"protocol",thesisWeights:[65,35]},{id:"brent-reserves",category:"macro",ticker:"BRENT",tags:["BRENT","OIL","ENERGY","USD/RUB","FERTILIZERS"],publishedAt:"2026-10-23",direction:"short",levels:{entry:80,target:72,invalidation:84,unit:"USD"},risk:"high",thesisWeights:[55,45]},{id:"dxy-rates",category:"macro",ticker:"DXY",tags:["DXY","EUR/USD","GBP/USD","USD/RUB","RATES","MACRO"],publishedAt:"2026-10-23",direction:"long",levels:{entry:103,target:106,invalidation:101.5,unit:"INDEX"},risk:"elevated",thesisWeights:[50,50]},{id:"macro-household",category:"macro",ticker:"MACRO",tags:["MACRO","HOUSEHOLD","INFLATION","BONDS","SGOV","VOO","VONG"],publishedAt:"2026-10-22",direction:"long",levels:{entry:100,target:104,invalidation:97,unit:"INDEX"},risk:"elevated",thesisWeights:[60,40]}];function o(e){return"string"==typeof e&&s.some(a=>a===e)}function r(e){return t.find(a=>a.id===e)}function n(e){return e.normalize("NFKC").toLocaleLowerCase().replace(RegExp("[^\\p{L}\\p{N}]","gu"),"")}function d(e){let{category:a,query:i="",copy:s}=e,o=i.trim().split(/\s+/u).map(n).filter(Boolean);return t.filter(e=>{if(a&&"all"!==a&&e.category!==a)return!1;let i=s[e.id],t=n([e.ticker,...e.tags,i.title,i.summary].join(" "));return o.every(e=>t.includes(e))})}function l(e){let{capital:a,primaryMovePct:i,hedgeMovePct:s,hedgePct:t,costPct:o}=e;if(![a,i,s,t,o].every(Number.isFinite)||a<=0||a>1e12||i<-100||i>100||s<-100||s>100||t<0||t>10||o<0||o>2)return null;let r=.1*a,n=a*t/100,d=r*i/100,l=-n*s/100,c=r*(1+i/100),p=n*(1+s/100),u=(r+c+n+p)*o/100,m=d+l-u,h=(r+c)*o/100;return{primaryNotional:r,hedgeNotional:n,reserve:a-r-n,primaryProfit:d,hedgeProfit:l,costs:u,netProfit:m,netReturnPct:m/a*100,unhedgedProfit:d-h,trancheEntries:[100,98,96],averageEntry:r/(.2*r/100+.3*r/98+.5*r/96)}}},87627:(e,a,i)=>{i.d(a,{X:()=>s});let s={ru:{"xau-dollar":{title:"Золото: отделяем долларовый шок от резерва капитала",summary:"Условная карта XAU/USD проверяет возврат после ложного пробоя на фоне сильного доллара и связывает результат с ликвидностью семьи.",assumption:"Только условные XAU/USD: вход 2 400 USD, цель 2 520, отмена 2 340. Это учебные уровни, не текущие котировки. Фактические доходности и потоки фондов не заявляются.",thesisA:"Если вынос под поддержку выкуплен, а реальные доходности перестают расти, подтверждённый ретест около 2 400 позволяет рассмотреть 2 520.",thesisB:"Если цена закрепляется ниже 2 340 при сильном долларе, структура лонга сломана: нужен пересмотр риска, а не усреднение.",sections:[{heading:"Два канала влияния на один семейный баланс",paragraphs:["На золото влияют и доверие к денежной системе, и альтернативная доходность инструмента без купона. Геополитический заголовок способен поддержать спрос, пока рост реальных ставок действует в обратную сторону. Поэтому сценарию нужны принятие цены и проверка ставок: громкая новость сама по себе не даёт основания для входа.","У семьи с физическим золотом и расходами в другой валюте риски отличаются от рисков трейдера с плечом. Важны хранение, спред дилера и пересчёт в валюту расходов. У серебра есть отдельный канал промышленного спроса, поэтому оно не обязано подтверждать каждое движение золота."]},{heading:"Сначала подтверждение, затем размер позиции",paragraphs:["Сценарий A требует выноса ликвидности вниз, закрытия над условной поддержкой и удержанного ретеста. В модели 120 USD потенциального роста против 60 USD структурного снижения до издержек. Соотношение 2:1 описывает геометрию цены, а не вероятность успеха; гэп способен перескочить уровень отмены.","В сценарии B сохраните резерв расходов и пересмотрите золото, долларовые деньги и акции совместно. Укрепление доллара способно одновременно снизить долларовую стоимость нескольких активов. До размещения капитала запишите тезис, размер и дату пересмотра; долгосрочный резерв не должен превращаться в источник торговой маржи."]}],action:"Отделите резервное золото от активного торгового капитала. Перед применением условных уровней проверьте предпосылки ставок и валют."},"nvda-duration":{title:"AI-акции: устойчивость прибыли против чувствительности оценки",summary:"NVDA задаёт условную карту AI-сектора. Качество выручки, денежный поток и ставка дисконтирования важнее одного отраслевого заголовка.",assumption:"Условная цена акции NVDA: вход 120 USD, цель 138, отмена 111. Текущая отчётность, оценочные мультипликаторы и котировки не заявляются.",thesisA:"Если качество прибыли подтверждается и ретест пробоя удерживает 120, можно рассмотреть поэтапный спотовый вход с пересмотром около 138.",thesisB:"Если ожидания спроса ухудшаются либо цена закрепляется ниже 111, сетап отменяется даже при привлекательной долгосрочной теме AI.",sections:[{heading:"Рост бизнеса не отменяет риск ставки",paragraphs:["Компания способна наращивать выручку при падении акций, если инвестор требует большую доходность от будущих денежных потоков. Концентрацию клиентов, превращение прибыли в деньги и обязательства по капитальным затратам проверяют раздельно. Сильная продуктовая история не доказывает приемлемый запас прочности при любой цене.","TSM, AVGO, MSFT, HOOD и AMD дают разные бизнес-модели, но несколько позиций всё равно зависят от одного цикла ликвидности и технологических расходов. Считать шесть тикеров шестью независимыми ставками означает недооценить общий фактор. До добавления ещё одной похожей акции проверьте весь секторный блок."]},{heading:"Спотовый лимит — потолок, не план загрузки",paragraphs:["AI-уровень MakeCash допускает максимум 10% капитала на сделку при 1x Spot. Это ограничение, не желательная доля. При условном входе 120 и отмене 111 полная десятипроцентная позиция несёт около 0,75% ценового риска всего портфеля до комиссий и гэпа. Индивидуальный бюджет может требовать меньшего размера.","Сценарий A требует ретеста и заранее назначенного пересмотра около 138. Сценарий B требует переоценки при 111 без превращения неудачной сделки в бессрочную инвестицию. Разрывы после отчётности, режим торгов и валюта брокерского счёта способны увеличить фактический убыток относительно модели расстояния до стопа."]}],action:"Покупайте AI-акции только при 1x Spot в пределах 10% на сделку. Проверьте общий технологический блок на рост ставок."},"btc-liquidity":{title:"Биткоин: возврат ликвидности прежде уверенности в направлении",summary:"Сценарий BTC/USD объединяет старшую структуру, проверку ETF-потоков и финансирования без выдачи старых наблюдений за текущие данные.",assumption:"Условные BTC/USD: вход 60 000 USD, цель 66 000, отмена 57 000. ETF-потоки, настроение и финансирование — условия для проверки, а не предоставленные текущие измерения.",thesisA:"Если вынос вниз выкуплен, старшая поддержка удержана, а ухудшение ETF-потоков прекратилось, рассматривается 60 000 с целью пересмотра 66 000.",thesisB:"Если цена закрепляется ниже 57 000 либо плечо растёт без спотового спроса, лонговый тезис отменяется, резерв сохраняется.",sections:[{heading:"Структура, потоки и перегрев отвечают на разные вопросы",paragraphs:["Вынос ликвидности показывает место вынужденных выходов, но не доказывает появление устойчивого спотового покупателя. Проверьте закрытие старшего таймфрейма и ретест возвращённой структуры. Одна быстрая свеча без принятия цены может оказаться закрытием шортов, а не устойчивой сменой спроса.","Чистые ETF-потоки описывают один канал спроса, а финансирование и открытый интерес — расположение позиций. Сильный страх не означает автоматическую покупку; рост с перегретым финансированием остаётся хрупким. Сопоставляйте даты наблюдений и отклоняйте вывод, собранный из несовместимых временных окон."]},{heading:"Доля капитала не равна риску убытка",paragraphs:["Основной уровень ограничивает долю сделки BTC, ETH или SOL десятью процентами капитала, плечо — 5x; только для BTC допустим отдельный максимальный потолок 10x. Это верхние границы политики, не инструкция. Дополнительно действует бюджет потерь до стопа: произведение доли на плечо увеличивает номинальную экспозицию.","При 1x условные вход 60 000 и отмена 57 000 дают 5% ценового расстояния. Десятипроцентная доля тогда означает около 0,5% риска всего капитала до издержек, если выход исполнится как задумано. Плечо, гэп, финансирование и ликвидация нарушают такую оценку. Провал сценария требует пересмотра, а не автоматического повышения плеча."]}],action:"Подтвердите возврат структуры и дату потоков. Рассчитайте размер из бюджета потерь, затем примените ограничения доли и плеча."},"eth-rotation":{title:"Ethereum: отличаем ротацию от общего отскока рынка",summary:"ETH/USD нуждается в собственном подтверждении. Рост долларовой котировки может сочетаться с ослаблением относительно BTC.",assumption:"Условные ETH/USD: вход 2 500 USD, цель 2 800, отмена 2 350. Относительная сила, потоки и сетевая активность — пункты исследования, не текущие измерения.",thesisA:"Если ETH удерживает возвращённый диапазон, а относительная сила стабилизируется без перегретого финансирования, рассматривается путь от 2 500 к 2 800.",thesisB:"Если возврат сломан ниже 2 350 или относительная слабость продолжается, общий отскок крипторынка не считается преимуществом именно ETH.",sections:[{heading:"Второй тикер способен повторять первый риск",paragraphs:["Ethereum и Bitcoin — разные активы, но часто зависят от общей долларовой ликвидности и готовности институциональных участников рисковать. Портфель с обоими лонгами может остаться одной направленной ставкой. До объявления ротации диверсификацией сравните ETH/BTC, спотовый спрос и позиции в деривативах.","ETF-потоки, спрос на транзакции и экономика стейкинга уточняют тезис, но измеряют разные механизмы и поступают с разной задержкой. Рост сетевой активности не гарантирует накопления стоимости токеном. Обоснованный обзор указывает период наблюдения и недостающие данные вместо уверенного заполнения пробелов рассказом."]},{heading:"Заранее опишите несостоявшуюся ротацию",paragraphs:["Сценарий A предполагает удержанный ретест около 2 500 и пересмотр около 2 800. Сценарий B считает закрепление ниже 2 350 сломом структуры. Геометрия 300 к 150 даёт 2:1 до издержек независимо от редакционного распределения внимания 50/50. Ни одно число не является частотой успешных прогнозов.","Потолок основной доли MakeCash остаётся 10% на сделку, а плеча для ETH — 5x. Отдельный максимальный предел 10x для BTC не переносится на ETH или SOL. Коррелированные позиции нуждаются в совместном стресс-тесте. При общем долларовом шоке уменьшение всей экспозиции важнее выбора более сильного тикера."]}],action:"Проверьте принятие цены именно ETH и относительную силу. Разделите бюджеты стопа, совместно контролируя общий риск ETH и BTC."},"defi-clmm":{title:"Концентрированная ликвидность: комиссии не равны доходности капитала",summary:"Эксперимент CLMM разделяет доход от комиссий, изменение запасов, непостоянные потери, газ и риск вывода.",assumption:"Условный индекс стоимости стратегии начинается со 100; цель пересмотра 103, защитный ориентир 95. Это не цена токена и не исполнимый вход. Фактическая APY и результаты протокола не заявляются.",thesisA:"Если объём внутри диапазона приносит достаточные комиссии, а вывод доступен, малый эксперимент может достичь индекса 103 после модельных издержек.",thesisB:"Если цена выходит из диапазона, стимулы слабеют или вывод затруднён, нужен пересмотр у 95; сбой контракта способен превысить этот ориентир.",sections:[{heading:"Сравнивайте альтернативу, а не рекламную APY",paragraphs:["Концентрированный пул получает комиссии, пока ликвидность активна в выбранном диапазоне. При движении цены меняется состав запасов: растущий счётчик комиссий может скрывать отставание от простого хранения двух активов. Оценивайте пул и альтернативу хранения на один момент времени.","Токены вознаграждения могут размываться, иметь вестинг или дорогой выход. Газ, ребалансировки, маршрутизация и проскальзывание уменьшают результат. Особенно нестабильна годовая ставка, выведенная из короткого периода. Эксперименту нужны дата начала, максимальный бюджет и чистая ликвидационная стоимость, а не только отображаемая доходность."]},{heading:"Три эшелона хранения ограничивают зону поражения",paragraphs:["Учебный план хранения распределяет 65% в холодный резерв, 25% в проверенную тёплую активность и 10% в горячие операции. Холодное хранение не подписывает контракты приложений. Это предпосылки планирования, не защита от любых отказов: разрешения и общие мосты способны связать кажущиеся отдельными позиции.","Для венчурной DEX-позиции малой капитализации согласованный уровень допускает 0,5%–1% общего капитала при 1x Spot. Он не разрешает плечо и не требует обязательного минимального вложения. До входа проверьте разблокировки, концентрацию держателей, права эмиссии и заморозки, ликвидность и глубину выхода. Защитный ориентир CLMM не заставит остановленный контракт исполнить вывод."]}],action:"Сравните чистую стоимость пула с хранением активов. Изолируйте холодный резерв; эксперимент малой капитализации не должен превышать 1%."},"stablecoin-custody":{title:"Стейблкоины: стабильная цена не означает доступ к капиталу",summary:"USDT и USDC могут сохранять видимую привязку, пока кошелёк, сеть, посредник или маршрут погашения становятся недоступны.",assumption:"Условный вход единицы 1,00 USD, учётная цель 1,01 и пересмотр выхода при потере привязки 0,98. В 1,01 включён гипотетический чистый доход: это не цель цены стейблкоина и не обещание выплаты.",thesisA:"Если резервы, сеть и погашение остаются надёжными, небольшая проверенная доходная позиция может накопить условные 0,01 чистого дохода на единицу.",thesisB:"При заморозке доступа, сбое моста или цене ниже 0,98 немедленно пересмотрите вывод и хранение; исполнение выхода не гарантируется.",sections:[{heading:"Четыре риска за одним знаком доллара",paragraphs:["Эмитент, блокчейн, маршрут хранения и доходный контракт — разные зависимости. Стабильная котировка не доказывает возможность конкретного владельца погасить или перевести актив. Отделяйте нативные токены от обёрнутых через мост; фиксируйте, кто способен остановить контракт, заморозить адрес либо ограничить счёт посредника.","Доходность может происходить из кредитования, базиса, стимулов или плеча, а не из безрисковой долларовой ставки. Проверьте реальный источник денежного потока и несовпадение сроков. Если вывод требует продажи неликвидного токена или ожидания очереди, семейный аварийный резерв нельзя считать немедленно доступным."]},{heading:"Разделите пути отказа и проверьте малый вывод",paragraphs:["Схема 65/25/10 для холодного, тёплого и горячего эшелонов показывает разделение функций. Кошельки холодного резерва не подключаются к приложениям и не выдают разрешений токенам. Два эмитента на одном мосту и подписи из одного скомпрометированного кошелька сохраняют общую точку отказа. Число токенов не равно диверсификации.","При 0,98 модель требует пересмотра выхода, не гарантированного стопа. Приостановка торгов, заморозка и перегрузка сети способны помешать действию, а контрагент доходности может потерять основной капитал даже без видимой потери привязки. До увеличения доли запишите альтернативный маршрут расходов и проверьте малый вывод."]}],action:"Не держите необходимые деньги в одном протоколе или маршруте погашения. Проверьте разрешения, происхождение токена и практическую доступность вывода."},"brent-reserves":{title:"Нефть: запасы и спрос способны отменить сделку по заголовку",summary:"Условный сценарий снижения BRENT связывает риск поставок со стоимостью топлива, валютами и покупательной способностью семьи.",assumption:"Условные BRENT: пересмотр шорта у 80 USD за баррель, цель 72, отмена 84. Текущие значения запасов, перевозок и спроса не предоставляются.",thesisA:"Если перебои ослабевают, запасы восстанавливаются, а спрос замедляется, неудачное закрепление выше 80 позволяет рассмотреть 72.",thesisB:"Если устойчивый шок предложения удерживает принятие цены выше 84, шортовый тезис сломан; политический календарь не оправдывает неограниченный убыток.",sections:[{heading:"Физические ограничения важнее политического календаря",paragraphs:["Нефть оценивает предельное предложение, транспорт и спрос, а не желаемый исход одного политика. Восстановление запасов ослабляет историю дефицита, но блокировка маршрута способна перевесить слабый спрос. До сделки разделите объявленную добычу, доставленные баррели и реально доступные хранилища.","Энергозатраты влияют на инфляцию, валюты производителей и сырьё удобрений с разными задержками. Семья может пострадать от дорогого топлива даже при росте энергетического актива. Связанная с экспортом валюта может реагировать на санкции и потоки капитала иначе, чем нефть. Каждый шаг причинной цепочки формулируйте как проверяемое условие."]},{heading:"У короткой позиции асимметричный риск провала",paragraphs:["Условные вход 80, цель 72 и отмена 84 дают соотношение 2:1 до издержек. Разрыв через 84 способен увеличить убыток, а перенос фьючерса и заём инструмента добавляют расходы. Модель не предполагает существования доступного контракта, брокерского допуска или гарантированной ликвидности.","Сценарий A требует неудачного принятия цены наверху, а не продажи исключительно из-за ощущения дорогой нефти. Сценарий B отменяет аргумент при устойчивом физическом дефиците. Сопоставьте топливные расходы семьи, товарные активы и валютные долги; небольшая аналитическая позиция не должна расходовать резерв обязательных платежей."]}],action:"Проверьте физическое предложение и принятие цены. Ограничьте риск гипотезы, сохранив деньги на энергию и долговые платежи."},"dxy-rates":{title:"Доллар: расхождение ставок становится тестом валют семьи",summary:"DXY помогает межрыночному анализу, но не заменяет проверку валюты, в которой семья зарабатывает, тратит и занимает.",assumption:"Условный индекс DXY: вход и пересмотр 103, цель 106, отмена 101,5. Текущие ключевые ставки, курсы и решения центробанков не заявляются.",thesisA:"Если ожидания ставок США остаются относительно жёсткими, а ретест удерживает 103, рассматривается движение к 106.",thesisB:"Если расхождение ставок сужается и индекс закрепляется ниже 101,5, долларовый тезис пересматривается без покупки по любой цене.",sections:[{heading:"Отделяйте индекс от валюты обязательства",paragraphs:["Сильный доллар способен удорожить долг для заёмщика с доходом в другой валюте, одновременно увеличивая пересчитанную стоимость долларовых сбережений. Эффект зависит от конкретной пары и дат денежных потоков. Веса DXY не повторяют каждую семейную экспозицию EUR/USD, GBP/USD или USD/RUB.","Ставки центробанков действуют через ожидаемую траекторию, инфляцию и движения капитала, а не через одну объявленную цифру. Уже учтённое снижение ставки может вызвать неожиданную реакцию валюты. Сравнивайте сценарий с доходностями облигаций и принятием цены вместо фиксированной связи между заголовком и следующим движением курса."]},{heading:"Согласуйте резерв расходов со сроками платежей",paragraphs:["Сценарий A использует условный возврат 103 и пересмотр 106; сценарий B отклоняет тезис ниже 101,5. Нормированные уровни демонстрируют процесс, не рекомендуют индексный инструмент. Полосы 50/50 распределяют исследовательское внимание между путями и не являются калиброванной вероятностью.","Распишите ипотеку, обучение и обязательные расходы по валютам и срокам. Резерв в валюте ближайшего обязательства способен уменьшить риск вынужденной конвертации даже ценой упущенного роста. До спекулятивной валютной позиции проверьте одновременное ослабление валюты дохода и удорожание рефинансирования."]}],action:"Разнесите доходы, резервы и долги по валютам. Используйте сценарий доллара для стресса, не для спекуляций деньгами ближайших платежей."},"macro-household":{title:"От макро к кошельку: шок ставки на семейном балансе",summary:"Стресс-карта семьи связывает инфляцию, суверенное финансирование и кредитные условия со вкладами, облигациями и обслуживанием долга.",assumption:"Условный индекс стоимости семейной корзины: база 100, пересмотр восстановления 104, стресс-пересмотр 97. Это учебная корзина, не ценная бумага и не прогноз доходности.",thesisA:"Если замедление инфляции сохраняется без резкого ухудшения занятости, диверсифицированная корзина может восстановиться к 104 при управляемых долгах.",thesisB:"Если рефинансирование дорожает одновременно с ослаблением дохода, у 97 нужен пересмотр защиты капитала даже при внешней диверсификации активов.",sections:[{heading:"Макрорежим попадает в кошелёк через денежные потоки",paragraphs:["Рост ставок способен улучшить доход вклада и одновременно снизить рыночную цену старых длинных облигаций. Переоформление долга может увеличить проценты раньше погашения нового вклада. Оценка только валовых активов скрывает проблему сроков: чистый капитал и календарь доступных денег нужны раздельно.","Занятость, доступность кредита и энергетическая инфляция способны ухудшаться вместе. Оценка недвижимости обновляется медленно, тогда как ипотечный платёж требуется сегодня. Акции, драгоценные металлы, недвижимость и стейблкоины имеют разные механизмы риска, но не становятся автоматически независимыми источниками ликвидности."]},{heading:"Сначала лестница платежей, затем распределение активов",paragraphs:["Сравнивайте вклады и облигации по сроку, ограничениям доступа и риску эмитента. SGOV, VOO и VONG несут разную дюрацию и фондовый риск; не все подходят на роль денег с фиксированной стоимостью. Объявленная годовая доходность не отменяет колебания цены, налоги и конвертационные расходы.","В обоих сценариях считайте валовые активы за вычетом всех обязательств, затем обновляйте доли после шока. Потолки 10% основных криптоактивов, 10% AI Spot и 1% DEX не требуют использования каждого лимита. При росте риска дохода меньшая активная доля и более сильный платёжный резерв согласуются с той же политикой."]}],action:"Не включайте долги в диаграмму долей активов, но вычитайте их из чистого капитала. Согласуйте погашения с расходами до активных вложений."}},en:{"xau-dollar":{title:"Gold: separate the dollar shock from the capital reserve",summary:"A conditional XAU/USD map tests a failed breakdown against a stronger dollar, then translates the result into household liquidity decisions.",assumption:"Illustrative XAU/USD only: entry 2,400 USD, target 2,520, invalidation 2,340. These are teaching levels, not current quotes. No actual yield or fund-flow observation is supplied.",thesisA:"If a sweep below support is reclaimed and real yields stop rising, a confirmed retest near 2,400 supports reviewing 2,520.",thesisB:"If price accepts below 2,340 while the dollar strengthens, the long structure fails; the correct response is a risk reduction review, not averaging down.",sections:[{heading:"Two channels, one household balance sheet",paragraphs:["Gold can respond to both monetary confidence and the opportunity cost of holding a non-yielding asset. A geopolitical headline can support demand while rising real yields create an opposing force. The scenario therefore requires price acceptance and a rate check; a dramatic headline alone does not establish an entry.","A family holding physical gold and spending in another currency faces different risks from a trader holding a leveraged instrument. Physical custody, dealer spreads and local currency translation matter. Silver also carries an industrial demand channel, so its movement need not confirm gold tick for tick."]},{heading:"Confirmation before allocation",paragraphs:["Scenario A looks for a downside liquidity sweep, a close back above the assumed support and a retest that holds. The model offers 120 USD of upside against 60 USD of structural downside before costs. This 2:1 ratio describes price geometry, not the probability of success; a gap can bypass invalidation.","Under scenario B, preserve the spending reserve and reassess exposure across gold, dollar cash and equities together. A stronger dollar can reduce the USD value of several holdings simultaneously. Record the thesis, position size and review date before committing capital; do not treat a long-term reserve as a source of trading margin."]}],action:"Separate reserve gold from the active trading sleeve. Recheck rate and currency assumptions before using these illustrative levels."},"nvda-duration":{title:"AI equities: earnings resilience versus valuation duration",summary:"NVDA anchors a conditional AI equity review. Revenue quality, cash conversion and discount rates matter more than one sector headline.",assumption:"Illustrative NVDA share price: entry 120 USD, target 138, invalidation 111. No current earnings, valuation multiple or market quote is asserted.",thesisA:"If earnings quality remains supported and a breakout retest holds near 120, review a staged spot position toward 138.",thesisB:"If demand expectations weaken or price accepts below 111, the setup fails even if the long-term AI theme remains attractive.",sections:[{heading:"Growth does not remove discount-rate risk",paragraphs:["A company can expand revenue while its share price falls when investors demand a higher return for future cash flows. Check customer concentration, cash conversion and capital expenditure commitments separately. A strong product narrative is not evidence that every price provides an acceptable margin of safety.","TSM, AVGO, MSFT, HOOD and AMD expose a portfolio to different business models, but several may still respond to the same liquidity and technology spending cycle. Counting six tickers as six independent bets understates common-factor risk. Review the combined sleeve before adding a seventh related position."]},{heading:"Use the spot rule as a ceiling",paragraphs:["The MakeCash AI equity tier permits at most 10% of capital per trade at 1x spot. This is a ceiling, not a desired allocation. With the assumed 120 entry and 111 invalidation, a full 10% position implies 0.75% portfolio price risk before fees or a gap; a smaller budget may be appropriate.","Scenario A requires a retest and a predefined review around 138. Scenario B requires reconsideration at 111 without converting a failed trade into an unlimited investment. Earnings gaps, trading hours and broker currency exposure can make realized losses larger than the simple stop-distance model."]}],action:"Keep AI stock entries at 1x spot, cap each at 10%, and stress the aggregate technology sleeve against higher rates."},"btc-liquidity":{title:"Bitcoin: liquidity reclaim before directional conviction",summary:"A BTC/USD scenario combines an HTF structure test, ETF-flow confirmation and a funding check without presenting stale observations as live data.",assumption:"Illustrative BTC/USD: entry 60,000 USD, target 66,000, invalidation 57,000. ETF flows, sentiment and funding are conditions to verify, not supplied live measurements.",thesisA:"If a downside sweep is reclaimed, HTF support holds and ETF-flow deterioration stops, review 60,000 toward 66,000.",thesisB:"If price accepts below 57,000 or leverage builds while spot demand fails, cancel the long thesis and protect the reserve.",sections:[{heading:"Structure, flows and crowding answer different questions",paragraphs:["A liquidity sweep can identify where forced exits occurred, but it does not prove that new spot buyers will sustain a rally. Check a higher-timeframe close and the retest of reclaimed structure. A single fast candle without acceptance may be a short-covering event rather than a durable change in demand.","ETF net flows describe one demand channel, while funding and open interest describe positioning. A high fear reading is not automatically a buy signal; a rising market with crowded funding can remain fragile. Use matching observation dates and reject a conclusion built from incompatible time windows."]},{heading:"Capital allocation is not loss risk",paragraphs:["The core tier caps allocation at 10% per BTC, ETH or SOL trade, with leverage up to 5x and an optional BTC-only 10x ceiling. Those are maximum policy limits, not instructions. The position must also satisfy a separate stop-loss budget; multiplying allocation by leverage can create much larger notional exposure.","At 1x the hypothetical 60,000 entry and 57,000 invalidation imply a 5% price distance. A 10% allocation therefore risks about 0.5% of total capital before costs if the exit fills as assumed. Leverage, gaps, funding and liquidation can break that simple estimate. A failed scenario calls for reassessment, not automatic leverage escalation."]}],action:"Confirm the reclaim and the flow date. Size from the structural loss budget, then apply the allocation and leverage ceilings."},"eth-rotation":{title:"Ethereum: distinguish relative rotation from a market-wide bounce",summary:"ETH/USD needs its own structural confirmation. A rising USD quote can coexist with weaker relative strength against BTC.",assumption:"Illustrative ETH/USD: entry 2,500 USD, target 2,800, invalidation 2,350. Relative strength, flows and network activity are research checks rather than live readings.",thesisA:"If ETH holds a reclaimed range and relative strength stabilizes without crowded funding, review 2,500 toward 2,800.",thesisB:"If the reclaim fails below 2,350 or relative weakness persists, avoid treating a broad crypto bounce as an ETH-specific advantage.",sections:[{heading:"A second ticker can repeat the first risk",paragraphs:["Ethereum and Bitcoin are different assets but often share dollar liquidity and institutional risk appetite. A portfolio long both can remain one directional bet. Compare the ETH/BTC relationship, spot demand and derivatives positioning before describing a rotation as diversification.","ETF flows, transaction demand and staking economics can inform a thesis, but they measure different mechanisms and may arrive with different delays. Rising on-chain activity does not guarantee value capture by a token. A credible brief states the observation period and the missing evidence rather than filling the gap with a confident narrative."]},{heading:"Define the failed rotation in advance",paragraphs:["Scenario A assumes a held retest near 2,500 and a review around 2,800. Scenario B treats acceptance below 2,350 as structural failure. The 300-to-150 price geometry is 2:1 before costs, independent of the editorial 50/50 attention split. Neither number is a forecast hit rate.","The MakeCash core allocation ceiling remains 10% per trade and 5x maximum for ETH; the BTC-only optional 10x limit does not transfer to ETH or SOL. Correlated positions still need a combined stress test. When the same dollar shock threatens every crypto holding, reducing total exposure may matter more than choosing a better ticker."]}],action:"Check ETH-specific acceptance and relative strength. Keep its stop budget separate from, and aggregate exposure consistent with, the BTC sleeve."},"defi-clmm":{title:"Concentrated liquidity: fee income is not the portfolio return",summary:"A CLMM experiment separates trading fees from inventory drift, impermanent loss, gas and withdrawal risk.",assumption:"Illustrative strategy NAV index starts at 100; review target 103 and loss guard 95. The index is not a token quote or an executable entry. No APY or protocol performance is claimed.",thesisA:"If volume earns enough fees inside the chosen range and exit liquidity remains available, a small experiment may reach index 103 net of modeled costs.",thesisB:"If price exits the range, rewards weaken or withdrawal access degrades, review at index 95; a contract failure can exceed this guard.",sections:[{heading:"Track the counterfactual, not the headline APY",paragraphs:["A concentrated pool earns fees only while liquidity is active in the selected range. As price moves, the inventory mix changes; a rising fee balance can conceal underperformance against simply holding the two assets. Record both the pool value and the hold benchmark using the same valuation timestamp.","Token incentives may dilute, vest or become expensive to sell. Gas, rebalancing, routing and exit slippage consume returns. An annualized rate from a short observation window is especially unstable. The experiment needs a start date, a maximum capital budget and a net liquidation value, not only a displayed yield."]},{heading:"Three custody echelons limit the blast radius",paragraphs:["An illustrative custody plan uses 65% cold reserve, 25% reviewed warm activity and 10% hot operations. Cold storage signs no application contracts. These are planning assumptions, not protection from all failures; approval exposure and correlated bridges can connect positions that appear separate.","For a DEX small-cap venture, the reconciled tier allows 0.5%–1% of total capital at 1x spot; it does not authorize leverage or a mandatory investment floor. Before committing, check unlocks, holder concentration, mint and freeze authority, liquidity and exit depth. A CLMM loss guard cannot enforce an on-chain exit when the contract is paused or liquidity disappears."]}],action:"Compare net pool NAV with the hold benchmark. Keep cold reserves isolated and size any small-cap experiment within the 1% ceiling."},"stablecoin-custody":{title:"Stablecoins: separate price stability from access to capital",summary:"USDT and USDC can retain a quoted peg while a wallet, chain, intermediary or redemption route becomes inaccessible.",assumption:"Illustrative unit entry 1.00 USD, accounting review target 1.01 and depeg exit review 0.98. The 1.01 includes hypothetical net income, not a stablecoin price target or a promised payout.",thesisA:"If reserves, chain access and redemption remain reliable, a small reviewed yield allocation may accumulate the assumed 0.01 net income per unit.",thesisB:"If access freezes, a bridge fails or a peg trades below 0.98, review withdrawal and custody immediately; exit execution is not assured.",sections:[{heading:"Four risks hide behind one dollar sign",paragraphs:["The issuer, the blockchain, the custody route and the yield contract are different dependencies. A stable quote does not prove that a specific holder can redeem or transfer. Separate native tokens from bridged representations and document who can pause a contract, freeze an address or restrict an intermediary account.","Yield can arise from lending, basis exposure, incentives or leverage rather than a risk-free dollar rate. Review the actual source of cash flow and any maturity mismatch. If withdrawals depend on selling a thin token or waiting through a queue, the household emergency reserve is not immediately available."]},{heading:"Diversify failure paths, then test a small withdrawal",paragraphs:["A 65/25/10 cold, warm and hot custody sketch illustrates segregation of duties. Cold reserve wallets do not connect to applications or grant token approvals. Holding two issuers on the same bridge and signing from one compromised wallet still leaves a shared failure path; token count alone is not diversification.","At 0.98 the model calls for an exit review, not a guaranteed stop. Trading halts, freezes and chain congestion may prevent action, and a yield counterparty can lose principal even without a visible depeg. Record an alternative spending route and test a small withdrawal before increasing exposure."]}],action:"Keep essential cash outside a single protocol or redemption route. Recheck permissions, native-chain provenance and practical withdrawal access."},"brent-reserves":{title:"Oil: storage and demand can overturn the headline trade",summary:"A conditional BRENT short scenario follows the path from supply risk to fuel costs, currencies and household purchasing power.",assumption:"Illustrative BRENT: short review at 80 USD per barrel, target 72, invalidation 84. Storage, shipping and demand figures are not supplied as current measurements.",thesisA:"If supply disruptions ease, inventories rebuild and demand softens, failed acceptance above 80 supports reviewing 72.",thesisB:"If a persistent supply shock keeps price accepted above 84, the short thesis fails; political timing cannot justify holding through unlimited loss.",sections:[{heading:"Follow physical constraints before political calendars",paragraphs:["Oil prices reflect marginal supply, transport and demand, not a single politician’s desired outcome. Inventory rebuilding can soften a shortage narrative, while blocked routes can overwhelm weak demand. Distinguish announced production, delivered barrels and usable storage before turning a headline into a position.","Energy costs affect inflation, producer currencies and fertilizer inputs with different lags. A household can be hurt by rising fuel costs even if an energy holding gains. An exporter-linked currency may react to sanctions or capital flows differently from oil itself. Write each causal step as a condition that can fail."]},{heading:"A short has asymmetric failure risk",paragraphs:["The hypothetical entry at 80, target at 72 and invalidation at 84 give a 2:1 price ratio before costs. A jump through 84 can produce a larger loss, and rolling futures or borrowed instruments add expenses. The model does not assume a tradable contract, broker access or guaranteed liquidity.","Scenario A requires failed upside acceptance rather than selling solely because oil seems expensive. Scenario B closes the original argument when physical scarcity persists. Review the portfolio’s energy bills, commodity exposure and currency debts together; a small analytical short should never consume the family’s repayment reserve."]}],action:"Validate physical supply and price acceptance. Treat the short as a bounded risk hypothesis and preserve cash for energy and debt obligations."},"dxy-rates":{title:"Dollar: rate divergence becomes a household currency test",summary:"DXY is a cross-market lens, not a substitute for checking the exact currency in which a family earns, spends and borrows.",assumption:"Illustrative DXY index: entry/review 103, target 106, invalidation 101.5. No current policy rate, spot FX quote or central-bank decision is asserted.",thesisA:"If US rate expectations remain relatively firm and the index holds 103 after a retest, review a move toward 106.",thesisB:"If rate divergence narrows and the index accepts below 101.5, reassess the dollar thesis and avoid adding at any price.",sections:[{heading:"Separate the index from the liability currency",paragraphs:["A stronger dollar can tighten financing for borrowers earning in another currency, while supporting the translated value of dollar savings. The effect depends on the actual currency pair and cash-flow dates. DXY weights do not reproduce every household’s EUR/USD, GBP/USD or USD/RUB exposure.","Central-bank rates matter through expected paths, inflation and capital flows rather than one announced number. A cut already priced into the market can produce an unexpected currency response. Check the scenario against bond yields and price acceptance instead of assuming a fixed link between a headline rate and the next FX move."]},{heading:"Match spending reserves to due dates",paragraphs:["Scenario A uses the assumed 103 reclaim and reviews 106; scenario B rejects the thesis below 101.5. These normalized index levels illustrate a process rather than a recommendation to trade an index product. The 50/50 bars allocate research attention to both paths and are not a calibrated forecast.","List each mortgage, tuition bill and essential expense by currency and maturity. A reserve matching the near-term liability can reduce forced conversion risk even when it sacrifices potential upside. Stress a weaker income currency and a higher refinancing cost together before adding speculative FX exposure."]}],action:"Map income, reserves and debts by currency. Use the dollar scenario as a stress input, not as permission to speculate with repayment cash."},"macro-household":{title:"Macro to wallet: a rate shock meets a family balance sheet",summary:"A household stress map connects inflation, sovereign financing and credit conditions to deposits, bond duration and debt service.",assumption:"Illustrative household asset basket NAV index: baseline 100, recovery review 104, stress review 97. The index is a teaching basket, not a market security or forecast return.",thesisA:"If disinflation holds without a sharp employment shock, a diversified basket may recover toward index 104 while liabilities remain manageable.",thesisB:"If refinancing costs rise as income weakens, review capital protection at index 97 even when headline assets still appear diversified.",sections:[{heading:"A macro regime reaches the wallet through cash flows",paragraphs:["Higher policy rates can improve deposit income yet lower the market price of existing long-duration bonds. A debt rollover can raise interest costs before a new deposit matures. Looking only at gross assets hides this timing problem; net worth and the calendar of spendable cash need separate views.","Employment, credit availability and energy inflation can move together in a stress regime. A property valuation may update slowly while a mortgage payment is immediately due. Treat equity indices, precious metals, real estate and stablecoins as different risk mechanisms, not automatically independent sources of liquidity."]},{heading:"Build a payment ladder before an allocation view",paragraphs:["Compare deposits and bonds by maturity, access restrictions and issuer risk. SGOV, VOO and VONG represent different duration and equity exposures and cannot all serve as a fixed-value cash substitute. A quoted annual yield does not remove price risk, taxes or currency conversion costs.","Model scenarios A and B using gross assets less all liabilities, then recalculate allocations after the shock. The 10% core-crypto ceiling, 10% AI spot ceiling and 1% DEX ceiling do not require using every allowance. When income risk rises, smaller active allocations and a stronger payment reserve can be consistent with the same policy."]}],action:"Keep liabilities out of asset-share charts, but subtract them from net worth. Align cash maturity with spending before choosing an active allocation."}},zh:{"xau-dollar":{title:"黄金与美元：先确认利率，再讨论避险",summary:"黄金不一定在股市下跌时上涨。把实际利率、美元需求和持仓规模放在同一张风险图里。",assumption:"2026-10-23 教学假设，非实时报价：XAU/USD 入场 2400、目标 2520、失效 2340 美元。A/B 条形表示情景权重，不是统计概率。",thesisA:"实际利率回落，美元走弱；黄金在回踩后保持结构。",thesisB:"现金需求推高美元，黄金同步承压；突破无法延续。",sections:[{heading:"从宏观变量到家庭资产",paragraphs:["黄金没有利息收入，因此持有现金或短期国债的实际回报上升时，黄金的相对吸引力可能下降。反过来，通胀预期保持稳定而名义利率下行，可能降低持金的机会成本。先区分利率变化的原因，再判断价格方向，避免把所有降息都解释成利好。","家庭以美元计价的资产和未来支出可能具有不同货币敞口。黄金有时分散风险，但流动性冲击中也可能被卖出以补足保证金。应同时记录现金缓冲、外币负债和黄金占比；两个资产过去负相关，并不能保证下次危机仍能相互对冲。"]},{heading:"确认、失效与执行纪律",paragraphs:["情景 A 需要美元动能减弱、实际利率不再上升，并且黄金回踩后重新站稳假设入场区。2400 到 2520 是教学测算路径，不是市场承诺。若跌破 2340 或宏观条件反转，应重新评估而非自动补仓；跳空与滑点会使实际损失超过计划。","每日检查美元、利率和成交结构，每次交易前更新资产总额与可承受损失。分批限价只能改变成交均价，不能修复错误逻辑。保护性空头同样有成本和亏损可能；对冲规模应由组合整体敞口决定，不能为了抵消一笔浮亏不断扩大风险。"]}],action:"在家庭资产表中检查黄金和美元敞口，记录失效条件与交易成本，再决定是否继续观察。"},"nvda-duration":{title:"人工智能股票：盈利增长与估值久期分开看",summary:"好公司也会遇到估值收缩。用现金流预期、利率敏感度和组合集中度检验 NVDA 情景。",assumption:"2026-10-23 教学假设，非实时报价：NVDA 入场 120、目标 138、失效 111 美元。情景权重不代表胜率。",thesisA:"盈利预期改善足以抵消估值压力，回踩得到买盘确认。",thesisB:"利率或增长预期恶化，估值压缩超过盈利改善。",sections:[{heading:"为什么增长不等于安全",paragraphs:["股票价格反映未来现金流，而不仅是已经公布的营收。即使收入增长，若市场原先预期更高，股价仍可能下跌。利率上行会降低远期利润的现值，因此高增长股票可能同时受到盈利修正与折现率变化影响；阅读财报时必须把这两条路径分开。","持有 NVDA、半导体 ETF 和大型科技指数，可能形成重复的人工智能敞口。资产名称不同不代表经济驱动不同。家庭还应考虑工作收入是否来自同一行业；工资与投资在压力期同时受损，会放大现金需求，此时现金储备比增加一只相似股票更有价值。"]},{heading:"把估值情景转成可检验规则",paragraphs:["情景 A 要求盈利与现金流预期不再被下调，价格回踩后保持结构，并得到成交量确认。假设 120 入场、138 目标与 111 失效只用于计算盈亏关系。跌破失效位或基本面假设变化，需要重新决策；财报跳空可能绕过止损价格。","MakeCash 人工智能股票层每笔配置上限为总资本的 10%，仅限 1x 现货；上限不是建议仓位。应把相关 ETF 与个股合并检查，扣除交易成本后评估结果。用分批买入管理执行节奏，不用借贷或加倍仓位来弥补一笔错误预测。"]}],action:"合并个股、ETF 与工资的行业敞口，再用 10% 上限和 1x 现货规则检查计划。"},"btc-liquidity":{title:"比特币流动性：净流入必须得到价格确认",summary:"ETF 流量、衍生品杠杆和高周期结构共同决定风险；任何单一指标都不能代替入场条件。",assumption:"2026-10-23 教学假设，非实时报价：BTC/USD 入场 60000、目标 66000、失效 57000 美元。A/B 为条件情景，不是预测概率。",thesisA:"现货需求吸收卖压，杠杆降温后价格守住结构。",thesisB:"资金流无法抵消抛售，拥挤多头触发连续平仓。",sections:[{heading:"资金流如何传导到持仓",paragraphs:["ETF 净流入描述一条需求渠道，并不覆盖所有交易场所、矿工卖出或长期持有人减仓。先检查数据日期、统计口径与结算延迟，再比较多日趋势。若净流入增加而价格不能上涨，可能意味着供应也在增加，不能直接把资金数字当作买入指令。","资金费率和未平仓量帮助识别杠杆拥挤，却不能单独给出顶部时间。强势行情可以长期保持正费率。家庭同时持有 BTC、ETH 与 SOL 时，应把它们视为可能共同下跌的风险组；保留交易所外的应急现金，避免市场下跌时被迫卖出。"]},{heading:"结构确认与资本上限",paragraphs:["情景 A 需要现货买盘延续、回踩获得承接，以及高周期低点未被破坏。60000、66000 与 57000 是教学价格。若结构跌破或流动性条件改变，情景失效；不要因为距离目标很远就忽视止损。波动、滑点与清算会使杠杆损失扩大。","核心 BTC/ETH/SOL 每笔配置不超过总资本 10%，杠杆上限 5x；BTC 可选上限 10x，绝非默认仓位。配置比例、名义敞口和止损风险需要分别核算。每日检查现货流量与杠杆指标，任何对冲也必须计入费用、融资与相关性变化。"]}],action:"先核对流量时间与结构，再检查核心层配置、名义敞口和最大可承受损失。"},"eth-rotation":{title:"以太坊轮动：相对强势比追涨更重要",summary:"ETH 上涨不一定代表独立需求。结合 ETH/BTC、现货流量和链上费用识别轮动是否持续。",assumption:"2026-10-23 教学假设，非实时报价：ETH/USD 入场 2500、目标 2800、失效 2350 美元。A/B 权重不代表统计胜率。",thesisA:"ETH 相对 BTC 走强，现货需求与链上活动相互印证。",thesisB:"美元价格跟随整体反弹，但相对结构和需求仍然疲弱。",sections:[{heading:"区分相对轮动与共同上涨",paragraphs:["若 ETH 与 BTC 同时上涨，应继续检查 ETH/BTC 是否形成更高低点。相对价格没有改善时，所谓轮动可能只是共同的美元流动性冲击。ETF 流量、现货成交和链上使用量分别观察需求的不同部分；它们不必同步，但出现背离时需要解释。","链上费用下降可能来自扩容效率，也可能来自活动减少，不能只按一个方向解读。质押收益需要扣除服务费与风险成本，收益率本身不保护币价。把现货、质押凭证及 DeFi 抵押中的 ETH 合并计算，避免同一资产在多个账户被低估敞口。"]},{heading:"情景边界与组合处理",paragraphs:["情景 A 需要相对结构改善、现货需求支持，并且回踩后能守住关键区域。2500 入场、2800 目标、2350 失效仅为教学假设。价格失效或相对强势消失时应重审计划，不能用长期叙事覆盖短期风险；波动可能造成无法按计划价格退出。","ETH 属于核心层：每笔配置最多 10%，杠杆上限 5x；BTC 的可选 10x 上限不适用于 ETH。已有 BTC 与 SOL 仓位必须同时纳入压力测试。每日查看相对价格和资金流，每周重核链上敞口，减少在相同风险源上重复下注。"]}],action:"合并现货、质押与 DeFi 中的 ETH，再检查相对结构及核心层限制。"},"defi-clmm":{title:"集中流动性：手续费收入不能遮住库存风险",summary:"CLMM 收益来自承担库存、区间和协议风险。用净资产指数比较费用收入与再平衡成本。",assumption:"2026-10-22 教学模型：净资产指数入场 100、目标 103、失效 95。指数不是币价，也不是可执行交易指令。",thesisA:"价格保持区间，净手续费覆盖库存变化与操作成本。",thesisB:"价格越界、单边库存或协议事件使净资产下降。",sections:[{heading:"从展示年化到净资产结果",paragraphs:["集中流动性把资本放进较窄价格区间，可能提高单位资本获得的手续费，也可能更快变成单边资产。展示年化通常把短期交易量外推，未必扣除无常损失、交易费与再平衡。应比较同一时间段内策略净资产与直接持币结果，而不是只看收入数字。","价格越出区间时，头寸可能停止赚取手续费；频繁调整区间又会增加链上成本。协议合约、预言机、管理权限与桥接路径各自带来风险。即使代币对看起来稳定，也需要明确退出路线，并在小额试验中验证赎回流程，不把历史运行当作安全保证。"]},{heading:"用指数观察，按风险边界行动",paragraphs:["本模型把初始净资产设为 100，103 表示扣费后的教学目标，95 表示重新评估策略的风险界线；这些不是可挂单的市场价格。情景 A 需要区间占用、成交与净费用持续成立。若越界或出现协议异常，不能为了恢复收益展示而机械追加资金。","冷钱包 65%、温钱包 25%、热钱包 10% 只是托管分层示例，冷层不连接合约。CLMM 的协议风险应从主动风险预算中单独扣除。DEX 小市值投机层每笔仅 0.5%–1%、1x 现货，不能把这个上限误当作所有流动性池的安全认证。"]}],action:"记录净资产、直接持币基准、区间时间和退出成本，先验证小额赎回流程。"},"stablecoin-custody":{title:"稳定币托管：锚定、冻结与赎回是三种风险",summary:"稳定币不是无风险银行现金。拆分发行人、交易平台、网络与智能合约敞口。",assumption:"2026-10-22 教学假设：参考值 1、目标 1.01、风险界线 0.98 美元。1.01 不保证溢价或收益；0.98 是退出评估警戒线。",thesisA:"锚定与赎回渠道正常，分层托管维持可用现金。",thesisB:"脱锚、冻结或提现中断使账面余额无法及时使用。",sections:[{heading:"余额相同，索偿路径不同",paragraphs:["直接持有稳定币、把币放在交易平台以及存入借贷协议，代表不同的索偿和操作路径。币价接近一美元只说明当前交易价格，不保证未来能按面值赎回。应确认发行人与储备披露、适用条件、链上地址权限，以及平台是否把资产再次用于借贷。","跨网络分散不一定分散发行人风险；两个网络上的同一稳定币可能共用冻结权限。若家庭生活开支依赖这些余额，还需要可直接使用的银行现金。收益产品应独立评估合约、清算与退出限制，不能把高收益当作储备质量或托管安全的证明。"]},{heading:"警戒线不是套利承诺",paragraphs:["参考 1 美元、目标 1.01 和警戒 0.98 仅用于教学情景。1.01 不代表保证获利，0.98 也不保证能成功退出。情景 A 需要赎回、交易深度与提现保持正常；若出现异常，应先验证可执行退出渠道，不盲目加仓等待回锚。","65% 冷层、25% 温层、10% 热层是示例而非推荐比例；冷层不与智能合约交互。托管分层不能消除发行人冻结风险。定期用小额测试提现，限制单平台与单协议余额，把恢复材料离线保存，并在组合中保留足以覆盖近期支出的现金。"]}],action:"按发行人、平台、网络与协议拆分余额，核对赎回路径并测试小额提现。"},"brent-reserves":{title:"原油与储备：供给标题必须经过需求检验",summary:"Brent 空头情景需要需求疲弱与可用供应同时成立；地缘事件可能迅速推翻路径。",assumption:"2026-10-23 教学假设，非实时报价：Brent 做空入场 80、目标 72、失效 84 美元。A/B 不是统计概率。",thesisA:"需求放缓，库存与可用供应形成缓冲，价格结构转弱。",thesisB:"运输中断或供给收缩造成短缺，价格突破失效位。",sections:[{heading:"把能源变化连接到家庭现金流",paragraphs:["原油库存需要结合季节、炼厂检修和运输周期解释。某周库存增加不一定代表最终需求崩塌，储备释放也只是把供应在时间上移动。观察需求与供应的多项证据，比追逐单条地缘新闻更稳健；所有数据先核对日期与是否经过修订。","能源上涨会通过交通、供暖、食品与企业成本传导到家庭；也可能推动通胀预期和利率。能源股票不等于原油本身，其结果还受债务、生产成本与资本开支影响。若家庭收入依赖能源行业，应把工资与投资一起压力测试，避免双重集中。"]},{heading:"空头情景的确认和失效",paragraphs:["情景 A 要求需求指标走弱、库存缓冲可用，并且反弹不能恢复原有结构。教学做空路径为 80 到 72，84 为失效。地缘冲击、跳空和流动性不足可能使退出价格更差；做空没有天然保护，价格上涨时会产生损失。","监控储备、期限结构与运输事件，信息改变时先降低确定性再重新测算。家庭预算应预留能源支出缓冲，不能靠投机收益支付必需账单。若用空头对冲其他资产，应记录合约规模、保证金、展期和融资成本，验证对冲与原始风险是否真正相关。"]}],action:"把油价压力加入家庭预算；交易计划同时记录空头成本、失效位与事件风险。"},"dxy-rates":{title:"美元指数与利差：强美元不等于所有货币同步下跌",summary:"DXY 是一篮子汇率指标。家庭实际货币敞口需要按收入、支出与债务逐项核算。",assumption:"2026-10-23 教学假设，非实时指数：DXY 入场 103、目标 106、失效 101.5。A/B 权重不代表统计胜率。",thesisA:"相对利差与避险需求支持美元，回踩保持上行结构。",thesisB:"政策预期反转或全球需求改善，美元结构跌破。",sections:[{heading:"利率渠道与现金需求渠道",paragraphs:["美元可能因美国利率相对较高而走强，也可能因全球投资者急需现金而上涨。两种原因对股票、黄金和信用市场的含义不同。先比较政策路径与流动性条件，再解释汇率；单次议息声明与市场真正计入的利率预期可能存在明显差别。","DXY 的货币权重不等于某个家庭的支出结构。美元指数上升时，本地货币仍可能出现不同走势。把房租、教育、旅游、工资与外币贷款按币种列出，计算未来现金缺口；若资产是美元而负债是另一种货币，汇率变动会改变净值与偿债压力。"]},{heading:"从指数观察到资产负债匹配",paragraphs:["情景 A 需要利差或现金需求继续支持美元，并且价格回踩后守住结构。103、106、101.5 仅为教学指数水平，不是实时信号。跌破失效区或政策条件改变时应重审。DXY 指数本身不是现金资产，相关产品的费用与跟踪差异需要另行计算。","定期检查外币负债与近期支出，优先匹配确定的现金需要，再考虑战术汇率交易。对冲并非免费，可能损失溢价或产生展期成本。不要同时把美元、黄金与股票都假设成必然获利；用多个方向同时不利的压力情景检验组合承受力。"]}],action:"按币种列出未来支出和债务，先补足现金匹配，再评估指数情景。"},"macro-household":{title:"宏观到家庭：用净资产抵御单一预测错误",summary:"家庭资本管理从现金需求、负债和可承受回撤开始，再讨论市场观点与资产配置。",assumption:"2026-10-22 教学篮子净资产指数：起点 100、观察目标 104、风险界线 97。不是可执行交易，也不是收益承诺。",thesisA:"收入与现金缓冲稳定，多资产组合吸收局部价格冲击。",thesisB:"失业、利率上升与资产回撤同时发生，现金缺口扩大。",sections:[{heading:"资产、负债与真实购买力",paragraphs:["家庭总资产并不等于可自由使用的财富。房产流动性较低，贷款仍需要按期偿还；把负债从总资产扣除才得到净资产。资产占比图只展示资产，不把贷款画成负资产扇区。记录本金、利率、月供与到期日，可以提前识别再融资和现金流压力。","同时用美元与 XAU \xd7 100 展示资产，有助于观察计价基准变化，但黄金价格波动也会改变换算结果。不得把黄金单位增加理解为无风险收益。存款到期收益应按真实日期、计息方式和费用计算，并与家庭需要支出的时间匹配，而非只挑最高年化。"]},{heading:"从宏观分歧到可执行家庭规则",paragraphs:["本模型将教学组合设为 100，104 是观察目标，97 是需要复核风险的界线。它们不是可以买卖的价格。情景 A 要求收入、储备与分散条件成立；情景 B 同时冲击就业、债务与资产。每月复核净值和现金缺口，重大事件发生时立即更新假设。","风险层上限不等于必须配置：核心 BTC/ETH/SOL 每笔 10%、最多 5x，BTC 可选上限 10x；人工智能股票每笔 10%、1x 现货；DEX 小市值每笔 0.5%–1%、1x 现货。先满足家庭应急与偿债资金，再评估这些上限，多个相关头寸不能绕过总风险预算。"]}],action:"先完善家庭资产、贷款与存款日期，再按收入中断和市场回撤同时发生的情景压力测试。"}},ko:{"xau-dollar":{title:"금과 달러: 안전자산이라는 이름보다 실질금리를 확인한다",summary:"주가 하락이 금 상승을 보장하지 않는다. 실질금리, 달러 수요, 가계의 통화 노출을 함께 살핀다.",assumption:"2026-10-23 교육용 가정이며 실시간 시세가 아니다. XAU/USD 진입 2400, 목표 2520, 무효화 2340달러. A/B 비중은 통계적 확률이 아니다.",thesisA:"실질금리와 달러 압력이 낮아지고 금 가격이 되돌림 이후 구조를 유지한다.",thesisB:"현금 수요가 달러를 밀어 올리고 금 매도까지 유발해 상승 구조가 무너진다.",sections:[{heading:"금리 변화가 가계 자산에 전달되는 경로",paragraphs:["금은 이자를 지급하지 않는다. 현금과 단기 국채의 실질 수익률이 오르면 금 보유의 기회비용도 커질 수 있다. 반대로 물가 기대가 안정된 상태에서 명목금리가 내려가면 부담이 줄어들 수 있다. 금리 인하 자체보다 그 배경이 성장 둔화인지 유동성 공급인지 구분해야 한다.","가계의 달러 자산과 미래 지출은 서로 다른 통화 위험을 가질 수 있다. 금은 일부 충격을 분산하지만 유동성 위기에는 증거금 마련을 위해 함께 매도되기도 한다. 금 비중만 보지 말고 현금 여유, 외화 부채, 소득 통화를 기록한다. 과거의 음의 상관관계가 다음 위기에도 유지된다는 보장은 없다."]},{heading:"확인 조건과 무효화 기준",paragraphs:["시나리오 A는 달러 상승세 둔화, 실질금리 안정, 되돌림 이후 매수세 회복이 함께 확인될 때 의미가 있다. 2400에서 2520으로 가는 경로는 교육용 계산이다. 2340 아래로 내려가거나 거시 조건이 반전되면 가정을 다시 평가한다. 갭과 슬리피지 때문에 실제 손실은 계획보다 커질 수 있다.","달러와 금리, 거래 구조는 매일 확인하고 거래 전에는 총자산과 감내 가능한 손실을 갱신한다. 분할 지정가는 평균 체결가를 바꿀 뿐 잘못된 논리를 고치지 않는다. 보호 목적의 숏도 손실과 비용을 낸다. 한 거래의 평가손실을 상쇄하려고 헤지 규모를 계속 늘리지 말고 전체 포트폴리오 노출로 결정한다."]}],action:"가계 자산표에서 금과 달러 노출을 확인하고 무효화 조건과 비용을 먼저 기록한다."},"nvda-duration":{title:"AI 주식: 이익 성장과 밸류에이션 민감도를 분리한다",summary:"좋은 기업도 높은 기대와 금리 변화로 하락할 수 있다. NVDA 시나리오를 현금흐름과 집중 위험으로 검증한다.",assumption:"2026-10-23 교육용 가정이며 실시간 시세가 아니다. NVDA 진입 120, 목표 138, 무효화 111달러. 시나리오 비중은 승률이 아니다.",thesisA:"이익 전망 개선이 할인율 부담을 상쇄하고 되돌림에 실수요가 유입된다.",thesisB:"금리 또는 성장 전망 악화로 밸류에이션 축소가 이익 증가보다 커진다.",sections:[{heading:"매출 증가가 손실 위험을 없애지 않는 이유",paragraphs:["주가는 이미 발표된 매출뿐 아니라 미래 현금흐름과 시장 기대를 반영한다. 매출이 늘어도 예상치에 못 미치면 주가가 하락할 수 있다. 금리 상승은 먼 미래 이익의 현재가치를 낮춘다. 따라서 실적을 읽을 때 사업 전망의 변화와 할인율의 변화를 따로 기록해야 가격 움직임을 과도하게 단순화하지 않는다.","NVDA, 반도체 ETF, 대형 기술주 지수를 동시에 보유하면 같은 AI 수요에 반복 노출될 수 있다. 이름이 다른 자산도 경제적 원인이 같을 수 있다. 가계 소득까지 같은 업종에 의존한다면 고용 충격과 투자 손실이 겹친다. 이때 비슷한 종목 하나를 추가하는 것보다 현금 완충 장치가 유용할 수 있다."]},{heading:"관점을 검증 가능한 실행 규칙으로 바꾼다",paragraphs:["시나리오 A는 이익과 현금흐름 전망의 하향 조정이 멈추고 가격 구조와 거래량이 이를 확인할 때 성립한다. 120 진입, 138 목표, 111 무효화는 교육용 수준이다. 가격 기준을 이탈하거나 사업 가정이 바뀌면 다시 판단한다. 실적 발표 뒤 갭이 발생하면 계획한 손절 가격에 체결되지 않을 수 있다.","MakeCash AI 주식 계층은 거래별 총자본 배분 상한 10%, 1x 현물만 허용한다. 상한은 권장 비중이 아니다. 관련 ETF와 개별 주식을 합산해 집중도를 점검하고 수수료를 뺀 결과를 계산한다. 분할 매수로 체결을 관리하되 차입이나 물타기 확대로 틀린 전망을 복구하려 하지 않는다."]}],action:"주식, ETF, 근로소득의 업종 노출을 합산한 뒤 10% 상한과 1x 현물 규칙을 확인한다."},"btc-liquidity":{title:"비트코인 유동성: 자금 유입은 가격의 확인이 필요하다",summary:"ETF 흐름, 파생상품 레버리지, 상위 시간대 구조를 함께 본다. 하나의 수치로 진입을 결정하지 않는다.",assumption:"2026-10-23 교육용 가정이며 실시간 시세가 아니다. BTC/USD 진입 60000, 목표 66000, 무효화 57000달러. A/B는 조건부 시나리오다.",thesisA:"현물 수요가 매도 물량을 흡수하고 레버리지 진정 후 가격 구조가 유지된다.",thesisB:"자금 유입보다 매도가 강하고 과도한 롱 포지션의 청산이 하락을 키운다.",sections:[{heading:"자금 흐름에서 가계 위험까지",paragraphs:["ETF 순유입은 하나의 수요 경로이며 모든 거래소, 채굴자 매도, 장기 보유자의 이익 실현을 포함하지 않는다. 날짜와 집계 방식, 결제 지연을 확인한 뒤 여러 날의 추세를 비교한다. 유입이 늘어도 가격이 오르지 않으면 공급도 늘고 있을 수 있다. 유입 수치를 곧바로 매수 신호로 해석하지 않는다.","펀딩비와 미결제약정은 레버리지 혼잡을 보여주지만 고점의 시간을 알려주지는 않는다. 강한 추세에서는 양의 펀딩이 오래 지속될 수 있다. 가계가 BTC, ETH, SOL을 보유한다면 동시에 하락할 수 있는 위험 묶음으로 계산한다. 생활비용 현금은 거래소 밖에 두어 급락 때 강제 매도를 피한다."]},{heading:"구조 확인과 자본 상한",paragraphs:["시나리오 A는 현물 매수 지속, 되돌림 지지, 상위 시간대 저점 유지가 함께 필요하다. 60000, 66000, 57000은 교육용 가격이다. 구조가 깨지거나 유동성 조건이 바뀌면 기존 시나리오를 무효화한다. 목표까지 거리가 멀다는 이유로 손절을 무시하지 않는다. 슬리피지와 청산은 레버리지 손실을 확대한다.","핵심 BTC/ETH/SOL 거래별 배분은 총자본의 최대 10%, 레버리지 상한은 5x다. BTC에만 선택적 10x 상한이 있으며 기본 설정이나 권장치가 아니다. 배분, 명목 노출, 손절 위험을 각각 계산한다. 현물 흐름과 레버리지를 매일 확인하고 헤지 비용, 조달 비용, 상관관계 변화도 전체 결과에 반영한다."]}],action:"자금 흐름의 날짜와 가격 구조를 확인한 뒤 배분, 명목 노출, 허용 손실을 따로 계산한다."},"eth-rotation":{title:"이더리움 순환매: 달러 가격보다 상대 강도를 먼저 본다",summary:"ETH 상승이 독립 수요를 뜻하지는 않는다. ETH/BTC, 현물 흐름, 온체인 사용을 연결해 확인한다.",assumption:"2026-10-23 교육용 가정이며 실시간 시세가 아니다. ETH/USD 진입 2500, 목표 2800, 무효화 2350달러. A/B 비중은 통계적 확률이 아니다.",thesisA:"ETH가 BTC 대비 강해지고 현물 수요와 온체인 활동이 이를 뒷받침한다.",thesisB:"시장 전체 반등에 동행하지만 상대 구조와 실제 수요는 개선되지 않는다.",sections:[{heading:"상대 순환매와 동반 상승을 구별한다",paragraphs:["ETH와 BTC가 함께 오른다면 ETH/BTC의 저점이 높아지는지 추가로 확인한다. 상대 가격이 개선되지 않으면 순환매처럼 보이는 움직임도 공통의 달러 유동성 충격일 수 있다. ETF 흐름, 현물 거래, 네트워크 사용은 수요의 다른 부분을 측정한다. 항상 동시에 움직일 필요는 없지만 차이가 생긴 이유를 설명해야 한다.","온체인 수수료 하락은 확장 효율 개선일 수도, 활동 감소일 수도 있다. 한 방향으로만 해석하지 않는다. 스테이킹 수익에서는 서비스 비용과 위험을 고려하며 수익률이 코인 가격을 보호하지 않는다는 점을 기억한다. 현물, 스테이킹 증표, DeFi 담보의 ETH를 합산하여 여러 계정에 흩어진 동일 자산 노출을 계산한다."]},{heading:"무효화 조건과 중복 노출",paragraphs:["시나리오 A는 상대 구조 개선, 현물 수요, 되돌림 지지가 필요하다. 진입 2500, 목표 2800, 무효화 2350은 교육용 수준이다. 가격 기준을 이탈하거나 상대 강도가 사라지면 다시 평가한다. 장기 서사가 단기 손실 규칙을 대체하지 않는다. 급변동에서는 계획한 가격으로 청산할 수 없을 수도 있다.","ETH는 핵심 계층이며 거래별 배분 상한 10%, 레버리지 상한 5x를 적용한다. BTC의 선택적 10x 상한을 ETH에 적용하지 않는다. 이미 보유한 BTC와 SOL도 같은 스트레스 시험에 포함한다. 상대 가격과 흐름은 매일, 온체인 합산 노출은 정기적으로 확인해 같은 위험 원인에 중복 투자하지 않는다."]}],action:"현물, 스테이킹, DeFi의 ETH를 합산하고 상대 강도와 핵심 계층 한도를 확인한다."},"defi-clmm":{title:"집중 유동성: 수수료 수입 뒤의 재고 위험을 계산한다",summary:"CLMM은 구간, 자산 재고, 프로토콜 위험을 부담한다. 표시 연환산 수익률보다 순자산을 비교한다.",assumption:"2026-10-22 교육용 순자산 지수: 시작 100, 목표 103, 재평가 기준 95. 토큰 가격이나 실행 가능한 거래 수준이 아니다.",thesisA:"가격이 구간 안에 머물고 순수수료가 재고 변화와 운영 비용을 상쇄한다.",thesisB:"구간 이탈, 단일 자산 편중, 프로토콜 사고가 순자산을 감소시킨다.",sections:[{heading:"표시 수익률에서 순자산 변화로",paragraphs:["집중 유동성은 좁은 가격 구간에 자본을 배치한다. 자본당 수수료가 늘 수 있지만 더 빠르게 한쪽 자산으로 바뀔 수도 있다. 표시 연환산 수익률은 짧은 거래량을 확대 계산하고 비영구적 손실이나 재조정 비용을 빼지 않을 수 있다. 동일 기간의 단순 보유와 전략 순자산을 함께 비교해야 한다.","가격이 구간을 벗어나면 수수료 발생이 멈출 수 있고 구간을 자주 옮기면 온체인 비용이 증가한다. 스마트 계약, 가격 오라클, 관리자 권한, 브리지 경로는 별개의 위험이다. 안정적인 자산 쌍도 안전을 보장하지 않는다. 소액으로 출금 경로를 확인하고 장애가 발생할 때 어느 자산으로 회수되는지 미리 기록한다."]},{heading:"교육용 지수와 수탁 경계",paragraphs:["모델은 초기 순자산을 100으로 놓는다. 103은 비용 차감 후 교육용 목표이며 95는 전략을 재검토할 위험 기준이다. 시장에 주문할 수 있는 가격이 아니다. 시나리오 A는 구간 체류와 순수수료 조건이 유지되어야 한다. 구간 이탈이나 계약 이상을 수익률 회복 목적의 자동 추가 예치로 해결하지 않는다.","콜드 65%, 웜 25%, 핫 10%는 수탁 계층의 예시이며 콜드 계층은 계약과 상호작용하지 않는다. CLMM의 프로토콜 위험은 별도 활성 위험 예산에서 계산한다. DEX 소형 토큰 계층의 거래별 0.5%–1%, 1x 현물 상한은 모든 유동성 풀에 대한 안전 인증도, 권장 배분도 아니다."]}],action:"순자산, 단순 보유 기준, 구간 체류 시간, 출금 비용을 기록하고 소액 회수부터 검증한다."},"stablecoin-custody":{title:"스테이블코인 수탁: 디페그, 동결, 상환 위험을 나눈다",summary:"스테이블코인은 무위험 은행 현금이 아니다. 발행사, 플랫폼, 네트워크, 계약 노출을 따로 기록한다.",assumption:"2026-10-22 교육용 가정: 기준 1, 목표 1.01, 위험 경계 0.98달러. 1.01은 수익 보장이 아니며 0.98은 출금 평가 경계다.",thesisA:"가격 연동과 상환 경로가 작동하고 분리된 수탁이 현금 접근성을 유지한다.",thesisB:"디페그, 주소 동결, 출금 중단으로 장부 잔액을 제때 사용할 수 없다.",sections:[{heading:"같은 잔액도 회수 경로는 다르다",paragraphs:["스테이블코인을 직접 보유하는 것, 거래소에 맡기는 것, 대출 계약에 예치하는 것은 서로 다른 회수 경로를 갖는다. 1달러 근처에서 거래된다는 사실이 미래의 액면 상환을 보장하지 않는다. 발행사 준비금 공개, 상환 조건, 주소 통제 권한을 확인한다. 플랫폼이 자산을 다시 대출하는지도 별도로 파악해야 한다.","여러 네트워크로 나눠도 같은 발행사의 동결 권한은 그대로일 수 있다. 생활비를 이 잔액에 의존한다면 직접 사용할 수 있는 은행 현금도 필요하다. 수익 상품의 계약, 청산, 출금 제한을 개별 평가한다. 높은 이자는 준비금의 질이나 수탁 안전을 증명하지 않으며 비상 상황에 유동성을 보장하지도 않는다."]},{heading:"위험 경계는 차익거래 약속이 아니다",paragraphs:["기준 1달러, 목표 1.01, 경계 0.98은 교육용 가정이다. 1.01에 도달하거나 이익이 난다는 보장은 없으며 0.98에서 출금이 체결된다는 보장도 없다. 시나리오 A는 상환과 시장 깊이, 출금이 유지될 때만 성립한다. 이상이 나타나면 재연동을 기대하며 추가 매수하기 전에 실제 회수 경로를 확인한다.","콜드 65%, 웜 25%, 핫 10%는 수탁 예시이며 권장 배분이 아니다. 콜드 계층은 스마트 계약에 연결하지 않지만 발행사 동결 위험까지 없애지는 못한다. 소액 출금을 정기 시험하고 단일 플랫폼과 프로토콜 잔액을 제한한다. 복구 자료는 오프라인으로 보관하며 가까운 시일의 필수 지출은 별도 현금으로 준비한다."]}],action:"발행사, 플랫폼, 네트워크, 계약별로 잔액을 나누고 상환 경로와 소액 출금을 확인한다."},"brent-reserves":{title:"원유와 비축: 공급 뉴스는 수요로 검증한다",summary:"Brent 숏은 수요 약화와 가용 공급이 함께 필요하다. 지정학적 충격은 이 조건을 빠르게 바꿀 수 있다.",assumption:"2026-10-23 교육용 가정이며 실시간 시세가 아니다. Brent 숏 진입 80, 목표 72, 무효화 84달러. A/B는 확률 예측이 아니다.",thesisA:"수요 둔화와 가용 재고가 완충 역할을 하고 가격 구조가 약해진다.",thesisB:"운송 차질이나 공급 감소로 부족이 발생해 무효화 수준을 돌파한다.",sections:[{heading:"에너지 가격이 가계 현금흐름에 미치는 영향",paragraphs:["원유 재고는 계절, 정유시설 정비, 운송 주기와 함께 해석해야 한다. 한 주의 재고 증가가 최종 수요 붕괴를 의미하지는 않는다. 전략 비축 방출도 공급 시점을 옮기는 조치다. 단일 지정학 뉴스보다 공급과 수요의 여러 증거를 비교한다. 자료의 날짜와 수정 여부를 먼저 확인해야 잘못된 비교를 피할 수 있다.","에너지 상승은 교통비, 난방비, 식품비, 기업 비용을 통해 가계에 전달되고 물가 기대와 금리에도 영향을 줄 수 있다. 에너지 기업 주식은 원유 자체가 아니다. 부채, 생산비, 설비투자가 수익을 바꾼다. 근로소득도 같은 산업에 의존한다면 투자와 임금을 함께 스트레스 시험해 이중 집중을 확인한다."]},{heading:"숏 시나리오의 확인과 무효화",paragraphs:["시나리오 A는 수요 지표 약화, 사용 가능한 재고, 반등 이후에도 회복되지 않는 가격 구조를 요구한다. 교육용 숏 경로는 80에서 72이며 84가 무효화 기준이다. 지정학적 갭과 얕은 유동성은 더 나쁜 가격에 청산하게 만들 수 있다. 숏은 자동 보호 수단이 아니며 가격 상승 시 손실이 발생한다.","비축, 선물 만기 구조, 운송 사건을 확인하고 정보가 바뀌면 먼저 가정의 확신도를 낮춘다. 가계 예산에는 에너지 지출 완충액을 두고 투기 수익으로 필수 청구서를 감당하려 하지 않는다. 다른 자산을 헤지한다면 계약 규모, 증거금, 롤오버와 조달 비용을 기록하고 원래 위험과 실제로 연결되는지 검증한다."]}],action:"가계 예산에 에너지 충격을 반영하고 숏 계획에는 비용, 무효화 수준, 사건 위험을 함께 기록한다."},"dxy-rates":{title:"달러 지수와 금리차: 모든 통화가 같은 방향은 아니다",summary:"DXY는 통화 바스켓 지수다. 가계의 실제 환위험은 소득, 지출, 부채 통화로 다시 계산한다.",assumption:"2026-10-23 교육용 지수 가정이며 실시간 값이 아니다. DXY 진입 103, 목표 106, 무효화 101.5. A/B 비중은 승률이 아니다.",thesisA:"상대 금리차와 현금 수요가 달러를 지지하며 되돌림 이후 상승 구조가 유지된다.",thesisB:"정책 기대 반전이나 글로벌 유동성 개선으로 달러 구조가 무너진다.",sections:[{heading:"금리 경로와 현금 수요 경로를 구별한다",paragraphs:["달러는 미국의 상대적으로 높은 금리 때문에 강해질 수도 있고 전 세계 투자자의 급한 현금 수요 때문에 오를 수도 있다. 두 원인은 주식, 금, 신용시장에 다른 의미를 갖는다. 정책 경로와 유동성 조건을 구분한 뒤 환율을 해석한다. 중앙은행의 한 번의 발표와 시장이 이미 반영한 기대 사이에는 차이가 있을 수 있다.","DXY의 통화 비중은 개별 가계의 지출 비중과 다르다. 지수가 상승해도 생활 통화는 별도로 움직일 수 있다. 월세, 교육, 여행, 임금, 외화 대출을 통화별로 정리하고 미래 부족액을 계산한다. 자산은 달러인데 부채는 다른 통화라면 환율 변화가 순자산과 상환 부담을 동시에 바꾼다."]},{heading:"지수 관찰을 현금 매칭으로 연결한다",paragraphs:["시나리오 A는 금리차 또는 현금 수요의 지지가 이어지고 되돌림에서 구조가 유지되어야 한다. 103, 106, 101.5는 교육용 지수 수준이며 실시간 신호가 아니다. 무효화 구간 이탈이나 정책 조건 변화가 발생하면 다시 판단한다. DXY 자체는 현금 자산이 아니며 관련 상품의 비용과 추적 차이는 별도로 계산한다.","외화 부채와 가까운 시기의 지출을 정기 확인해 확정된 현금 수요부터 맞춘다. 그다음 전술적 환율 거래를 검토한다. 헤지는 무료가 아니며 프리미엄 손실이나 롤오버 비용이 발생할 수 있다. 달러, 금, 주식이 모두 이익을 준다고 가정하지 말고 여러 방향이 동시에 불리해지는 스트레스 조건도 시험한다."]}],action:"미래 지출과 부채를 통화별로 정리하고 현금 수요를 맞춘 뒤 지수 시나리오를 검토한다."},"macro-household":{title:"거시 전망에서 가계로: 한 번의 예측 오류를 견디는 순자산",summary:"가계 자본 관리는 시장 전망보다 현금 수요, 부채, 감내할 수 있는 손실에서 시작한다.",assumption:"2026-10-22 교육용 바스켓 순자산 지수: 시작 100, 관찰 목표 104, 위험 경계 97. 실행 가능한 거래나 수익 보장이 아니다.",thesisA:"소득과 현금 여유가 유지되고 분산 자산이 일부 시장 충격을 흡수한다.",thesisB:"실직, 금리 상승, 자산 하락이 겹치며 가계 현금 부족이 커진다.",sections:[{heading:"자산, 부채, 구매력을 따로 계산한다",paragraphs:["총자산이 곧 자유롭게 쓸 수 있는 부는 아니다. 부동산은 현금화가 느리지만 대출 상환은 계속된다. 총자산에서 부채를 빼야 순자산이 된다. 자산 비중 차트에는 자산만 넣고 대출을 음의 조각으로 넣지 않는다. 원금, 금리, 월 상환액, 만기일을 기록하면 차환과 현금흐름 압력을 미리 볼 수 있다.","달러와 XAU \xd7 100으로 함께 표시하면 기준 통화 변화가 보이지만 금 가격 자체도 환산 값을 바꾼다. 금 단위 증가를 무위험 수익으로 해석하지 않는다. 예금 만기 수령액은 실제 날짜, 복리 방식, 비용을 반영한다. 가장 높은 연이율만 고르지 말고 가족의 지출 시점과 예금 회수 시점을 맞춘다."]},{heading:"다른 전망에도 유지되는 가계 규칙",paragraphs:["모델의 교육용 포트폴리오는 100에서 시작하며 104는 관찰 목표, 97은 위험 재평가 기준이다. 매매할 수 있는 가격이 아니다. 시나리오 A는 소득, 준비금, 분산 조건이 유지되어야 한다. 시나리오 B는 고용과 부채, 자산을 동시에 압박한다. 매월 순자산과 현금 부족액을 점검하고 큰 사건이 발생하면 가정을 갱신한다.","계층별 상한은 투자 의무가 아니다. 핵심 BTC/ETH/SOL은 거래별 10%, 최대 5x이며 BTC만 선택적 10x 상한이다. AI 주식은 거래별 10%, 1x 현물이고 DEX 소형 토큰은 0.5%–1%, 1x 현물이다. 비상금과 상환 자금을 먼저 확보한다. 상관성이 큰 여러 거래로 전체 위험 예산을 우회하지 않는다."]}],action:"가계 자산, 대출, 예금 날짜를 완성하고 소득 중단과 시장 하락이 겹치는 상황을 시험한다."}},es:{"xau-dollar":{title:"Oro y d\xf3lar: comprobar los tipos reales antes de buscar refugio",summary:"Una ca\xedda burs\xe1til no garantiza una subida del oro. Los tipos reales, la demanda de d\xf3lares y la exposici\xf3n familiar deben analizarse juntos.",assumption:"Supuesto educativo del 2026-10-23, sin cotizaciones en directo: XAU/USD, entrada 2400, objetivo 2520 e invalidaci\xf3n 2340 USD. Los pesos A/B no son probabilidades estad\xedsticas.",thesisA:"Bajan los tipos reales y la presi\xf3n del d\xf3lar; el oro conserva su estructura tras un retroceso.",thesisB:"La necesidad de efectivo fortalece al d\xf3lar y provoca ventas de oro; la ruptura no se sostiene.",sections:[{heading:"Del tipo real al balance familiar",paragraphs:["El oro no paga intereses. Cuando aumenta la rentabilidad real del efectivo o de la deuda p\xfablica a corto plazo, puede subir el coste de oportunidad de mantenerlo. Una bajada de tipos nominales con expectativas de inflaci\xf3n estables puede aliviar ese coste. Antes de interpretar el movimiento, conviene distinguir entre desaceleraci\xf3n econ\xf3mica y expansi\xf3n de liquidez.","Los activos en d\xf3lares y los gastos futuros de una familia pueden tener exposiciones distintas. El oro puede diversificar algunos riesgos, pero en una crisis de liquidez tambi\xe9n puede venderse para cubrir garant\xedas. Hay que registrar reservas de efectivo, deudas en otras monedas y peso del metal. Una correlaci\xf3n hist\xf3rica negativa no garantiza protecci\xf3n futura."]},{heading:"Confirmaci\xf3n, invalidaci\xf3n y ejecuci\xf3n",paragraphs:["El escenario A requiere menor presi\xf3n del d\xf3lar, estabilizaci\xf3n de los tipos reales y demanda tras el retroceso. La trayectoria de 2400 a 2520 es un ejercicio, no una promesa. Por debajo de 2340, o si cambian las condiciones macroecon\xf3micas, debe revisarse la tesis. Los saltos de precio y el deslizamiento pueden superar la p\xe9rdida prevista.","Se revisan d\xf3lar, tipos y estructura diariamente, y el capital disponible antes de cada operaci\xf3n. Las entradas por tramos modifican el precio medio, pero no reparan una tesis equivocada. Una cobertura corta tambi\xe9n pierde dinero y tiene costes. Su tama\xf1o depende de la exposici\xf3n total, no del deseo de compensar una p\xe9rdida aislada."]}],action:"Revisar la exposici\xf3n familiar a oro y d\xf3lares; registrar invalidaci\xf3n y costes antes de decidir."},"nvda-duration":{title:"Acciones de IA: separar crecimiento y sensibilidad de valoraci\xf3n",summary:"Una buena empresa puede caer por expectativas exigentes o tipos m\xe1s altos. NVDA necesita una tesis de beneficios y un l\xedmite de concentraci\xf3n.",assumption:"Supuesto educativo del 2026-10-23, sin cotizaciones en directo: NVDA, entrada 120, objetivo 138 e invalidaci\xf3n 111 USD. Los pesos no representan tasas de acierto.",thesisA:"La mejora de beneficios compensa la presi\xf3n de valoraci\xf3n y el retroceso encuentra demanda.",thesisB:"Los tipos o unas expectativas m\xe1s d\xe9biles comprimen la valoraci\xf3n m\xe1s de lo que mejoran los beneficios.",sections:[{heading:"Crecer no elimina el riesgo de precio",paragraphs:["La cotizaci\xf3n refleja flujos de caja futuros y expectativas, no solo ventas publicadas. Los ingresos pueden crecer mientras la acci\xf3n cae si el mercado esperaba m\xe1s. Un tipo de descuento mayor reduce el valor presente de beneficios lejanos. Separar revisiones operativas y cambios de tipos evita atribuir todo movimiento a una noticia empresarial.","NVDA, un ETF de semiconductores y un \xedndice tecnol\xf3gico pueden repetir la misma exposici\xf3n a la demanda de IA. Los nombres distintos no garantizan diversificaci\xf3n. Si el salario familiar depende del mismo sector, el empleo y la cartera pueden sufrir a la vez. Una reserva de efectivo puede aportar m\xe1s resistencia que otra acci\xf3n muy correlacionada."]},{heading:"Convertir la valoraci\xf3n en reglas comprobables",paragraphs:["El escenario A exige que dejen de empeorar las previsiones de beneficios y caja, con confirmaci\xf3n de estructura y volumen. Entrada 120, objetivo 138 e invalidaci\xf3n 111 son niveles did\xe1cticos. Una ruptura o un cambio empresarial obliga a revisar el plan. Tras resultados puede haber un salto que impida ejecutar la salida al precio previsto.","La capa de acciones de IA limita cada asignaci\xf3n al 10% del capital total, exclusivamente en contado 1x. Es un m\xe1ximo, no una recomendaci\xf3n. Deben sumarse ETF y acciones relacionadas, y descontarse los costes del resultado. Fraccionar compras organiza la ejecuci\xf3n; endeudarse o ampliar posiciones para recuperar un error aumenta la exposici\xf3n."]}],action:"Sumar exposici\xf3n de acciones, ETF e ingresos laborales; comprobar el m\xe1ximo del 10% y contado 1x."},"btc-liquidity":{title:"Liquidez de Bitcoin: las entradas de capital necesitan confirmaci\xf3n",summary:"Flujos de ETF, apalancamiento y estructura de largo plazo forman una lectura conjunta. Ning\xfan indicador sustituye las condiciones de entrada.",assumption:"Supuesto educativo del 2026-10-23, sin cotizaciones en directo: BTC/USD, entrada 60000, objetivo 66000 e invalidaci\xf3n 57000 USD. A/B son escenarios condicionales.",thesisA:"La demanda al contado absorbe ventas y la estructura resiste despu\xe9s de moderarse el apalancamiento.",thesisB:"Las ventas superan los flujos y las liquidaciones de posiciones largas amplifican la ca\xedda.",sections:[{heading:"De los flujos al riesgo del hogar",paragraphs:["Los flujos netos de ETF describen un canal de demanda, no todos los mercados ni las ventas de mineros o grandes tenedores. Primero se comprueban fecha, metodolog\xeda y retrasos de liquidaci\xf3n; despu\xe9s se compara la tendencia de varios d\xedas. Si aumentan las entradas sin avanzar el precio, tambi\xe9n puede estar creciendo la oferta.","La financiaci\xf3n y el inter\xe9s abierto ayudan a detectar acumulaci\xf3n de apalancamiento, pero no se\xf1alan por s\xed solos el momento de un techo. Una tendencia puede mantener financiaci\xf3n positiva durante tiempo. BTC, ETH y SOL deben tratarse como exposiciones que pueden caer juntas. El efectivo para necesidades familiares debe permanecer separado del margen de negociaci\xf3n."]},{heading:"Confirmar la estructura y limitar el capital",paragraphs:["El escenario A necesita compras al contado persistentes, apoyo tras un retroceso y conservaci\xf3n de m\xednimos relevantes. Los niveles 60000, 66000 y 57000 son educativos. Si falla la estructura o cambia la liquidez, la tesis queda invalidada. La distancia al objetivo no justifica ignorar la salida; deslizamiento y liquidaciones aumentan el riesgo apalancado.","Cada operaci\xf3n principal en BTC/ETH/SOL tiene un m\xe1ximo de asignaci\xf3n del 10% y apalancamiento m\xe1ximo 5x. Solo BTC admite un techo opcional 10x, nunca una configuraci\xf3n recomendada. Asignaci\xf3n, exposici\xf3n nominal y p\xe9rdida hasta invalidaci\xf3n se calculan por separado. La revisi\xf3n diaria incorpora flujos, financiaci\xf3n, costes de cobertura y cambios de correlaci\xf3n."]}],action:"Verificar fecha de los flujos y estructura; calcular asignaci\xf3n, exposici\xf3n nominal y p\xe9rdida tolerable por separado."},"eth-rotation":{title:"Rotaci\xf3n hacia Ethereum: comprobar fuerza relativa antes de perseguir precio",summary:"Una subida de ETH puede ser un movimiento general del mercado. ETH/BTC, demanda al contado y actividad ayudan a distinguirla.",assumption:"Supuesto educativo del 2026-10-23, sin cotizaciones en directo: ETH/USD, entrada 2500, objetivo 2800 e invalidaci\xf3n 2350 USD. Los pesos A/B no son probabilidades.",thesisA:"ETH mejora frente a BTC con apoyo de demanda al contado y actividad de red.",thesisB:"El precio acompa\xf1a el rebote general, pero la estructura relativa y la demanda siguen d\xe9biles.",sections:[{heading:"Rotaci\xf3n relativa frente a subida compartida",paragraphs:["Cuando ETH y BTC suben a la vez, debe comprobarse si ETH/BTC forma m\xednimos crecientes. Sin mejora relativa, la aparente rotaci\xf3n puede responder al mismo impulso de liquidez en d\xf3lares. Los flujos de ETF, el volumen al contado y el uso de la red miden aspectos diferentes. Las divergencias requieren explicaci\xf3n, no una selecci\xf3n del indicador m\xe1s favorable.","Unas comisiones de red menores pueden reflejar eficiencia de escalado o menos actividad. No tienen una interpretaci\xf3n \xfanica. La rentabilidad de participaci\xf3n debe evaluarse despu\xe9s de gastos y riesgos, y no protege la cotizaci\xf3n. Se suman ETH al contado, recibos de participaci\xf3n y garant\xedas DeFi para no ocultar exposici\xf3n repetida entre cuentas."]},{heading:"L\xedmites de tesis y exposici\xf3n compartida",paragraphs:["El escenario A exige fuerza relativa, demanda al contado y apoyo en el retroceso. Entrada 2500, objetivo 2800 e invalidaci\xf3n 2350 son supuestos did\xe1cticos. La p\xe9rdida de estructura o de fortaleza relativa obliga a revisar la operaci\xf3n. Una narrativa de largo plazo no sustituye un l\xedmite de riesgo; la volatilidad puede impedir salir al nivel previsto.","ETH pertenece a la capa principal: asignaci\xf3n m\xe1xima del 10% por operaci\xf3n y apalancamiento m\xe1ximo 5x. El techo opcional 10x de BTC no se aplica a ETH. Las posiciones existentes de BTC y SOL entran en la misma prueba de estr\xe9s. Se revisan precios relativos y flujos diariamente, y exposici\xf3n conjunta con regularidad."]}],action:"Sumar ETH al contado, en participaci\xf3n y en DeFi; comprobar estructura relativa y l\xedmites de la capa principal."},"defi-clmm":{title:"Liquidez concentrada: las comisiones no ocultan el riesgo de inventario",summary:"CLMM combina riesgo de rango, inventario y protocolo. El valor neto aporta m\xe1s informaci\xf3n que una rentabilidad anualizada aislada.",assumption:"Modelo educativo del 2026-10-22: \xedndice de patrimonio inicial 100, objetivo 103 y revisi\xf3n de riesgo 95. No es un precio ni una operaci\xf3n ejecutable.",thesisA:"El precio permanece en rango y las comisiones netas compensan inventario y costes.",thesisB:"La salida de rango, la concentraci\xf3n en un activo o un incidente reducen el patrimonio.",sections:[{heading:"De la rentabilidad anunciada al patrimonio neto",paragraphs:["La liquidez concentrada coloca capital dentro de un intervalo estrecho. Puede cobrar m\xe1s comisiones por unidad de capital y convertirse antes en un solo activo. La anualizaci\xf3n de un periodo breve puede omitir p\xe9rdida impermanente y reajustes. Deben compararse, durante las mismas fechas, el patrimonio de la estrategia y el resultado de mantener los activos.","Fuera del rango pueden detenerse las comisiones; moverlo con frecuencia a\xf1ade gastos de red. Contratos, or\xe1culos, permisos administrativos y puentes son riesgos distintos. Una pareja de activos aparentemente estable no garantiza seguridad. Conviene probar una retirada peque\xf1a y registrar qu\xe9 activo se recuperar\xeda ante una incidencia antes de comprometer m\xe1s capital."]},{heading:"\xcdndice educativo y fronteras de custodia",paragraphs:["El modelo normaliza el patrimonio inicial a 100. El 103 es un objetivo did\xe1ctico despu\xe9s de gastos y 95 activa la revisi\xf3n del riesgo; no son precios para cursar \xf3rdenes. El escenario A requiere permanencia en rango y comisiones netas suficientes. Un problema de contrato o rango no se resuelve con aportaciones autom\xe1ticas para recuperar rentabilidad.","Una distribuci\xf3n de custodia del 65% fr\xedo, 25% templado y 10% caliente es ilustrativa; la capa fr\xeda no interact\xfaa con contratos. CLMM necesita un presupuesto separado de riesgo de protocolo. El m\xe1ximo por operaci\xf3n del 0.5%–1%, contado 1x, para peque\xf1os tokens DEX no certifica la seguridad de cualquier fondo de liquidez."]}],action:"Registrar patrimonio, referencia de tenencia, tiempo en rango y coste de salida; validar una retirada peque\xf1a."},"stablecoin-custody":{title:"Custodia de monedas estables: separar paridad, bloqueo y reembolso",summary:"Una moneda estable no equivale a efectivo bancario sin riesgo. Emisor, plataforma, red y contratos requieren controles distintos.",assumption:"Supuesto educativo del 2026-10-22: referencia 1, objetivo 1.01 y alerta 0.98 USD. El objetivo no garantiza prima o beneficio; la alerta exige evaluar la salida.",thesisA:"La paridad y los canales de reembolso funcionan y la custodia separada mantiene acceso al efectivo.",thesisB:"La p\xe9rdida de paridad, un bloqueo o una suspensi\xf3n de retiradas impiden usar el saldo.",sections:[{heading:"El mismo saldo no implica el mismo derecho",paragraphs:["Mantener una moneda estable, depositarla en una plataforma y prestarla mediante un contrato son rutas de recuperaci\xf3n distintas. Cotizar cerca de un d\xf3lar no garantiza el reembolso futuro a valor nominal. Se revisan informaci\xf3n de reservas, condiciones del emisor, permisos de bloqueo y posible reutilizaci\xf3n de activos por la plataforma. Cada dependencia a\xf1ade una capa de riesgo.","Repartir fondos entre redes puede conservar el mismo riesgo de emisor y la misma capacidad de congelaci\xf3n. Si el hogar depende del saldo para vivir, necesita tambi\xe9n efectivo bancario utilizable. Los productos de rendimiento exigen evaluar contratos, liquidaciones y restricciones de salida. Un inter\xe9s alto no demuestra reservas de calidad ni disponibilidad en una crisis."]},{heading:"Una alerta no es una promesa de arbitraje",paragraphs:["Referencia 1 USD, objetivo 1.01 y alerta 0.98 son supuestos educativos. No se garantiza beneficio a 1.01 ni una salida ejecutada a 0.98. El escenario A necesita reembolso, profundidad y retiradas operativas. Ante una anomal\xeda, primero se comprueba una ruta real de recuperaci\xf3n; comprar m\xe1s esperando restaurar la paridad puede aumentar la p\xe9rdida.","La divisi\xf3n 65% fr\xedo, 25% templado y 10% caliente es un ejemplo, no una recomendaci\xf3n. La capa fr\xeda no conecta contratos, pero no elimina bloqueos del emisor. Se prueban retiradas peque\xf1as, se limitan saldos por plataforma y protocolo y se conservan respaldos fuera de l\xednea. Los gastos pr\xf3ximos requieren una reserva accesible independiente."]}],action:"Desglosar saldos por emisor, plataforma, red y contrato; comprobar reembolso y retirada con una cantidad peque\xf1a."},"brent-reserves":{title:"Petr\xf3leo y reservas: contrastar los titulares de oferta con la demanda",summary:"El escenario corto de Brent necesita demanda d\xe9bil y oferta disponible. Una interrupci\xf3n geopol\xedtica puede invalidarlo r\xe1pidamente.",assumption:"Supuesto educativo del 2026-10-23, sin cotizaciones en directo: Brent corto, entrada 80, objetivo 72 e invalidaci\xf3n 84 USD. A/B no son probabilidades.",thesisA:"La menor demanda y unas reservas disponibles amortiguan la oferta mientras se debilita la estructura.",thesisB:"Los problemas de transporte o producci\xf3n crean escasez y superan el nivel de invalidaci\xf3n.",sections:[{heading:"Del barril al flujo de caja familiar",paragraphs:["Las existencias necesitan contexto estacional, mantenimiento de refiner\xedas y ciclos de transporte. Un aumento semanal no prueba un colapso de demanda final. Liberar reservas tambi\xe9n desplaza oferta entre momentos. Es mejor contrastar varias se\xf1ales de oferta y consumo que reaccionar a un titular. Fecha y revisiones de datos importan para evitar comparaciones equivocadas.","La energ\xeda se transmite al hogar mediante transporte, calefacci\xf3n, alimentos y costes empresariales, y puede elevar inflaci\xf3n esperada y tipos. Una acci\xf3n energ\xe9tica no replica el barril: deuda, costes de extracci\xf3n e inversi\xf3n alteran su resultado. Si el empleo familiar depende del sector, ingresos y cartera deben someterse juntos a estr\xe9s para detectar concentraci\xf3n."]},{heading:"Confirmaci\xf3n e invalidaci\xf3n del corto",paragraphs:["El escenario A exige demanda m\xe1s d\xe9bil, reservas utilizables y rebotes incapaces de reconstruir la estructura. El recorrido educativo es de 80 a 72, con invalidaci\xf3n en 84. Saltos geopol\xedticos y poca profundidad pueden empeorar la salida. Una posici\xf3n corta no protege por naturaleza: pierde cuando el precio sube y a\xf1ade costes operativos.","Se supervisan reservas, estructura de vencimientos y transporte, reduciendo convicci\xf3n cuando cambian los datos. El presupuesto familiar debe incluir un colch\xf3n energ\xe9tico; los gastos esenciales no deben depender de beneficios especulativos. Para una cobertura se registran nominal, garant\xedas, renovaci\xf3n y financiaci\xf3n, comprobando que el instrumento responde al riesgo que pretende compensar."]}],action:"A\xf1adir un choque energ\xe9tico al presupuesto y registrar costes, invalidaci\xf3n y eventos en cualquier plan corto."},"dxy-rates":{title:"D\xf3lar y diferenciales: un \xedndice fuerte no describe todas las monedas",summary:"DXY es una cesta de divisas. La exposici\xf3n familiar debe calcularse con monedas reales de ingresos, gastos y deudas.",assumption:"Supuesto educativo del 2026-10-23, sin valor en directo: DXY, entrada 103, objetivo 106 e invalidaci\xf3n 101.5. Los pesos A/B no son tasas de acierto.",thesisA:"Los diferenciales relativos y la demanda de efectivo sostienen al d\xf3lar tras un retroceso.",thesisB:"Cambian las expectativas monetarias o mejora la liquidez global y se pierde la estructura.",sections:[{heading:"Distinguir tipos de inter\xe9s y demanda de efectivo",paragraphs:["El d\xf3lar puede subir por unos tipos estadounidenses relativamente altos o porque los inversores necesitan efectivo con urgencia. Las consecuencias para acciones, oro y cr\xe9dito son distintas. Primero se separan pol\xedtica monetaria y liquidez. Un comunicado de un banco central puede diferir mucho de las expectativas ya descontadas, por lo que el titular no explica todo el movimiento.","Las ponderaciones de DXY no coinciden con los gastos de una familia. La moneda local puede comportarse de otra forma aunque suba el \xedndice. Alquiler, educaci\xf3n, viajes, salarios y pr\xe9stamos deben ordenarse por divisa. Cuando activos y deudas tienen monedas diferentes, el tipo de cambio modifica tanto el patrimonio como la capacidad de pago."]},{heading:"Del \xedndice a la correspondencia de obligaciones",paragraphs:["El escenario A requiere continuidad del apoyo de tipos o efectivo y conservaci\xf3n de estructura tras el retroceso. Los niveles 103, 106 y 101.5 son educativos, no se\xf1ales en directo. Una ruptura o un cambio monetario exige revisar la tesis. DXY no es efectivo; los productos vinculados tienen costes y diferencias de seguimiento propios.","Se revisan deudas en divisas y pagos cercanos para cubrir primero necesidades conocidas de efectivo. Despu\xe9s puede evaluarse una operaci\xf3n t\xe1ctica. Una cobertura puede perder primas o acumular costes de renovaci\xf3n. No debe suponerse que d\xf3lar, oro y acciones siempre aportar\xe1n ganancias; tambi\xe9n se prueban escenarios con varias exposiciones movi\xe9ndose en contra al mismo tiempo."]}],action:"Ordenar pagos y deudas por moneda, cubrir necesidades de efectivo y despu\xe9s evaluar el escenario del \xedndice."},"macro-household":{title:"De la macroeconom\xeda al hogar: patrimonio que resiste un error de pron\xf3stico",summary:"La gesti\xf3n familiar empieza por efectivo, obligaciones y p\xe9rdidas tolerables. Las opiniones de mercado llegan despu\xe9s.",assumption:"Modelo educativo del 2026-10-22: cesta patrimonial normalizada a 100, objetivo de observaci\xf3n 104 y revisi\xf3n de riesgo 97. No es una operaci\xf3n ni una promesa de rentabilidad.",thesisA:"Ingresos, reservas y diversificaci\xf3n permiten absorber un golpe parcial en los mercados.",thesisB:"Desempleo, tipos m\xe1s altos y ca\xeddas de activos coinciden y ampl\xedan el d\xe9ficit de efectivo.",sections:[{heading:"Separar activos, obligaciones y poder adquisitivo",paragraphs:["Los activos brutos no son riqueza inmediatamente disponible. Un inmueble puede tardar en venderse mientras la hipoteca sigue venciendo. El patrimonio neto resta obligaciones a activos; la deuda no debe dibujarse como una porci\xf3n negativa del gr\xe1fico de activos. Principal, inter\xe9s, cuota y vencimiento ayudan a anticipar presi\xf3n de refinanciaci\xf3n y caja.","Mostrar USD y XAU \xd7 100 permite comparar bases de valoraci\xf3n, pero el precio del oro tambi\xe9n cambia la conversi\xf3n. M\xe1s unidades de oro no equivalen a rendimiento sin riesgo. El dep\xf3sito se calcula con fechas reales, capitalizaci\xf3n y gastos. Su vencimiento debe coincidir con las necesidades del hogar, en lugar de elegir \xfanicamente la tasa anual mayor."]},{heading:"Reglas familiares que sobreviven a opiniones distintas",paragraphs:["La cesta educativa parte de 100; 104 es un objetivo de observaci\xf3n y 97 exige revisar riesgos. No son niveles negociables. El escenario A necesita ingresos, reservas y diversificaci\xf3n; el B combina presi\xf3n sobre empleo, deuda y activos. Patrimonio y d\xe9ficit de caja se revisan mensualmente y despu\xe9s de acontecimientos que cambien las condiciones familiares.","Los techos no obligan a invertir: BTC/ETH/SOL, m\xe1ximo 10% por operaci\xf3n y 5x, con techo opcional BTC 10x; acciones de IA, 10% y contado 1x; peque\xf1os tokens DEX, 0.5%–1% y contado 1x. Emergencias y amortizaciones se cubren primero. Varias operaciones correlacionadas no deben utilizarse para eludir el presupuesto total de riesgo."]}],action:"Completar activos, pr\xe9stamos y fechas de dep\xf3sitos; probar p\xe9rdida de ingresos y ca\xedda de mercados simult\xe1neas."}}}},93059:(e,a,i)=>{i.d(a,{g:()=>s});let s={en:{title:"MakeCash Analytics Desk",introduction:"Four editorial verticals connect market structure to household capital. These dated educational scenarios use declared illustrative levels; they are not a daily live feed or individual recommendations.",all:"All verticals",search:"Search ticker or theme",searchPlaceholder:"BTC, XAU, BRENT, DXY, NVDA, DeFi…",clear:"Clear search",results:"Scenario briefs",empty:"No scenarios match these filters. Change the ticker or show all verticals.",reset:"Reset filters",read:"Read full scenario",close:"Close scenario",back:"Back to scenarios",missing:"This scenario is unavailable. Select a published brief below.",published:"Published",assumption:"Illustrative assumptions",thesis:"Conditional scenarios A / B",weights:"Editorial attention weights, not measured probabilities.",entry:"Entry / review level",target:"Target / review level",invalidation:"Invalidation / exit review",dollarUnit:"USD",indexUnit:"Normalized index",long:"Long scenario",short:"Short scenario",audit:"Check ticker in trade audit",action:"Capital decision",readerLabel:"Full analytical scenario",categories:{markets:"Markets & Equities",crypto:"Crypto & Smart Money",defi:"DeFi & On-Chain Yield",macro:"Macro & Geopolitics"},risks:{elevated:"Elevated cross-asset risk",high:"High market risk",protocol:"Protocol & custody risk"},strategyTitle:"Why a Single Forecast Error Never Stops a Hedged Portfolio from Capturing Profit",strategyIntro:"A worked portfolio example, not a profit promise. A hedge can offset one wrong thesis when its own payoff is favorable. Both legs can lose, and costs can turn a gross gain into a net loss.",strategyExplain:["Split a 10% primary allocation into three filled spot tranches: 20% at 100, 30% at 98, 50% at 96. Units, not price averages, determine the combined cost basis. Unfilled orders, gaps and timing would change this result.","A separate short exposure can offset the long only if its underlying falls sufficiently. The two price moves below are independent; set both unfavorably to see basis risk. This unlevered notional model reserves the hedge budget and does not model borrowing, funding, margin calls or liquidation.","A “free short” means assigning previously realized profit to a defined loss budget. It does not make shorting free or safe. A stop may slip; financing and an unlimited adverse move can exceed that budget. Never transfer the entire household reserve into a hedge."],simulator:"Interactive hedge payoff",portfolio:"Model portfolio, USD",legMove:"Primary long move from average entry, %",hedgeMove:"Hedge underlying price move, %",hedgeSize:"Hedge notional / portfolio, %",slippage:"Fee + slippage per side, %",modelCost:"Modeled total costs",legResult:"Primary long P&L",hedgeResult:"Short hedge P&L",netResult:"Combined net P&L",unhedged:"Same long without hedge, net",outcome:"Model outcome",profit:"Net gain in this model",loss:"Net loss in this model",flat:"Break-even in this model",tranche:"Three-tranche execution",trancheWeights:"Filled 20% / 30% / 50%",averageEntry:"Unit-weighted average entry",freeShort:"What “free short” means",modelOnly:"Educational model only. All three entries are assumed filled. Return moves start from each leg’s own cost basis; no executions or real portfolio results are claimed.",invalidInput:"Enter a portfolio above zero, finite price moves from −100% to 100%, hedge size from 0% to 10%, and costs from 0% to 2%.",more:"Open strategy and model",less:"Collapse strategy and model"},ru:{title:"Аналитический деск MakeCash",introduction:"Четыре направления связывают структуру рынка с капиталом семьи. Датированные учебные сценарии используют явно заданные условные уровни. Это не ежедневная лента котировок и не персональные рекомендации.",all:"Все направления",search:"Поиск по тикеру или теме",searchPlaceholder:"BTC, XAU, BRENT, DXY, NVDA, DeFi…",clear:"Очистить поиск",results:"Сценарные обзоры",empty:"По этим фильтрам сценариев нет. Измените тикер или откройте все направления.",reset:"Сбросить фильтры",read:"Читать полный сценарий",close:"Закрыть сценарий",back:"Вернуться к сценариям",missing:"Этот сценарий недоступен. Выберите опубликованный обзор ниже.",published:"Опубликовано",assumption:"Условные предпосылки",thesis:"Условные сценарии A / B",weights:"Вес внимания редакции, не измеренная вероятность.",entry:"Вход / уровень пересмотра",target:"Цель / уровень пересмотра",invalidation:"Отмена / пересмотр выхода",dollarUnit:"USD",indexUnit:"Нормированный индекс",long:"Сценарий роста",short:"Сценарий снижения",audit:"Проверить тикер в аудите сделок",action:"Решение для капитала",readerLabel:"Полный аналитический сценарий",categories:{markets:"Рыночная аналитика и акции",crypto:"Криптоиндустрия и Умные Деньги",defi:"DeFi и ончейн-доходность",macro:"Макроэкономика и геополитика"},risks:{elevated:"Повышенный межрыночный риск",high:"Высокий рыночный риск",protocol:"Риск протокола и хранения"},strategyTitle:"Почему ошибка в одном прогнозе не мешает забрать профит",strategyIntro:"Разбор портфельного примера, не обещание прибыли. Хедж способен компенсировать ошибку одной идеи при благоприятном результате самого хеджа. Обе позиции могут быть убыточными, а издержки могут превратить валовую прибыль в чистый убыток.",strategyExplain:["Разделите основную спотовую позицию размером 10% капитала на три исполненных транша: 20% по 100, 30% по 98, 50% по 96. Среднюю себестоимость определяет число единиц актива. Неисполненные заявки, гэпы и время исполнения изменят результат.","Отдельная короткая позиция компенсирует лонг только при достаточном снижении её базового актива. Два движения цены ниже независимы: задайте оба неблагоприятно и проверьте базисный риск. Модель номинала без плеча резервирует бюджет хеджа; заём, финансирование, маржинальные требования и ликвидация не моделируются.","\xabБесплатный шорт\xbb означает выделение части уже зафиксированной прибыли в ограниченный бюджет потерь. Это не делает шорт бесплатным или безопасным. Проскальзывание стопа, финансирование и неограниченный рост цены могут превысить бюджет. Не направляйте в хедж весь семейный резерв."],simulator:"Интерактивная модель хеджа",portfolio:"Модельный портфель, USD",legMove:"Движение лонга от средней цены, %",hedgeMove:"Движение базового актива хеджа, %",hedgeSize:"Номинал хеджа / портфель, %",slippage:"Комиссия и проскальзывание на сторону, %",modelCost:"Совокупные модельные издержки",legResult:"Результат основного лонга",hedgeResult:"Результат короткого хеджа",netResult:"Совокупный чистый результат",unhedged:"Тот же лонг без хеджа, чистыми",outcome:"Результат модели",profit:"Чистая прибыль в этой модели",loss:"Чистый убыток в этой модели",flat:"Безубыток в этой модели",tranche:"Исполнение тремя траншами",trancheWeights:"Исполнено 20% / 30% / 50%",averageEntry:"Средняя цена по числу единиц",freeShort:"Что означает \xabбесплатный шорт\xbb",modelOnly:"Только учебная модель. Все три входа считаются исполненными. Движения рассчитываются от собственной себестоимости каждой позиции. Исполнение и результаты реального портфеля не заявляются.",invalidInput:"Введите портфель больше нуля, конечные движения цены от −100% до 100%, хедж от 0% до 10% и издержки от 0% до 2%.",more:"Открыть стратегию и модель",less:"Свернуть стратегию и модель"},zh:{title:"MakeCash 分析台",introduction:"四个编辑方向把市场结构与家庭资本联系起来。这些标明日期的教学情景使用明确的示例水平，并非每日实时报价或个人投资建议。",all:"全部方向",search:"搜索代码或主题",searchPlaceholder:"BTC、XAU、BRENT、DXY、NVDA、DeFi…",clear:"清除搜索",results:"情景分析",empty:"没有符合筛选条件的情景。请更改代码或查看全部方向。",reset:"重置筛选",read:"阅读完整情景",close:"关闭情景",back:"返回情景列表",missing:"该情景不可用。请从下方选择已发布的分析。",published:"发布日期",assumption:"示例假设",thesis:"条件情景 A / B",weights:"编辑关注权重，不是测得的概率。",entry:"入场 / 复核水平",target:"目标 / 复核水平",invalidation:"失效 / 退出复核",dollarUnit:"美元",indexUnit:"标准化指数",long:"上涨情景",short:"下跌情景",audit:"在交易审计中查看代码",action:"资本决策",readerLabel:"完整分析情景",categories:{markets:"市场与股票",crypto:"加密资产与聪明钱",defi:"DeFi 与链上收益",macro:"宏观与地缘政治"},risks:{elevated:"跨资产风险偏高",high:"市场风险高",protocol:"协议与托管风险"},strategyTitle:"为什么一次预测失误不妨碍对冲组合获取利润",strategyIntro:"这是组合教学案例，并非盈利承诺。只有对冲本身取得有利结果时，它才可能抵消一项错误判断。两条腿也可能同时亏损，成本可能让毛利润变成净亏损。",strategyExplain:["把占总资本 10% 的主要现货仓位分成三笔已成交份额：20% 在 100、30% 在 98、50% 在 96。合并成本由买入数量决定，而非简单平均价格。未成交订单、跳空和成交时点都会改变结果。","独立空头只有在其标的充分下跌时才能抵消多头。下方两个价格变化相互独立；可同时设置为不利方向，观察基差风险。此无杠杆名义模型预留对冲预算，不计算借贷、资金费、追加保证金或强平。","“免费空头”是指从已经实现的利润中分配明确的亏损预算，并不意味着做空免费或安全。止损滑点、融资成本及无上限的逆向涨幅都可能突破预算。切勿把全部家庭储备投入对冲。"],simulator:"交互式对冲收益模型",portfolio:"模型组合，美元",legMove:"主要多头相对平均成本的变化，%",hedgeMove:"对冲标的价格变化，%",hedgeSize:"对冲名义额 / 组合，%",slippage:"单边费用与滑点，%",modelCost:"模型总成本",legResult:"主要多头盈亏",hedgeResult:"空头对冲盈亏",netResult:"合计净盈亏",unhedged:"相同多头不对冲的净盈亏",outcome:"模型结果",profit:"本模型净盈利",loss:"本模型净亏损",flat:"本模型盈亏平衡",tranche:"三笔分批执行",trancheWeights:"假设已成交 20% / 30% / 50%",averageEntry:"按数量计算的平均成本",freeShort:"“免费空头”的含义",modelOnly:"仅供教学。假设三笔订单全部成交。两项价格变化均从各自成本计算，不声称真实执行或组合业绩。",invalidInput:"请输入大于零的组合金额、−100% 至 100% 的有限价格变化、0% 至 10% 的对冲比例和 0% 至 2% 的成本。",more:"展开策略与模型",less:"收起策略与模型"},ko:{title:"MakeCash 분석 데스크",introduction:"네 가지 분석 분야가 시장 구조를 가계 자본과 연결합니다. 날짜가 표시된 교육용 시나리오는 명시적인 예시 가격을 사용하며, 일일 실시간 시세나 개인 투자 권고가 아닙니다.",all:"모든 분야",search:"종목 코드 또는 주제 검색",searchPlaceholder:"BTC, XAU, BRENT, DXY, NVDA, DeFi…",clear:"검색 지우기",results:"시나리오 분석",empty:"필터와 일치하는 시나리오가 없습니다. 종목을 변경하거나 모든 분야를 확인하세요.",reset:"필터 초기화",read:"전체 시나리오 읽기",close:"시나리오 닫기",back:"시나리오 목록으로",missing:"이 시나리오는 사용할 수 없습니다. 아래에서 발행된 분석을 선택하세요.",published:"발행일",assumption:"예시 가정",thesis:"조건부 시나리오 A / B",weights:"편집상 주목 비중이며 측정된 확률이 아닙니다.",entry:"진입 / 재검토 수준",target:"목표 / 재검토 수준",invalidation:"무효화 / 청산 재검토",dollarUnit:"미국 달러",indexUnit:"정규화 지수",long:"상승 시나리오",short:"하락 시나리오",audit:"거래 감사에서 종목 확인",action:"자본 의사결정",readerLabel:"전체 분석 시나리오",categories:{markets:"시장과 주식",crypto:"암호화폐와 스마트 머니",defi:"DeFi와 온체인 수익",macro:"거시경제와 지정학"},risks:{elevated:"자산 간 위험 상승",high:"높은 시장 위험",protocol:"프로토콜 및 보관 위험"},strategyTitle:"한 번의 예측 오류가 헤지 포트폴리오의 수익 확보를 막지 않는 이유",strategyIntro:"수익 약속이 아닌 포트폴리오 교육 사례입니다. 헤지 자체의 결과가 유리해야 한 가지 잘못된 판단을 상쇄할 수 있습니다. 두 포지션 모두 손실을 낼 수 있으며 비용 때문에 총이익이 순손실로 바뀔 수 있습니다.",strategyExplain:["총자본 10%의 기본 현물 포지션을 체결된 세 주문으로 나눕니다. 100에서 20%, 98에서 30%, 96에서 50%입니다. 단순 가격 평균이 아니라 매수 수량으로 통합 원가를 계산합니다. 미체결, 갭, 체결 시점은 결과를 바꿉니다.","별도의 숏 포지션은 그 기초자산이 충분히 하락할 때만 롱을 상쇄합니다. 아래 두 가격 변화는 독립적입니다. 둘 다 불리하게 설정해 베이시스 위험을 확인하세요. 무레버리지 명목 모델은 헤지 예산을 예약하며 차입, 펀딩, 추가 증거금, 강제 청산은 계산하지 않습니다.","“무료 숏”은 이미 실현한 이익 일부를 정해진 손실 예산에 배정한다는 뜻입니다. 숏이 무료이거나 안전하다는 의미가 아닙니다. 손절 슬리피지, 금융 비용, 상한 없는 역방향 상승은 예산을 초과할 수 있습니다. 가계 준비금 전체를 헤지에 넣지 마세요."],simulator:"대화형 헤지 손익 모델",portfolio:"모델 포트폴리오, USD",legMove:"평균 원가 대비 기본 롱 변동, %",hedgeMove:"헤지 기초자산 가격 변동, %",hedgeSize:"헤지 명목액 / 포트폴리오, %",slippage:"편도 수수료와 슬리피지, %",modelCost:"모델 총비용",legResult:"기본 롱 손익",hedgeResult:"숏 헤지 손익",netResult:"합산 순손익",unhedged:"헤지 없는 동일 롱의 순손익",outcome:"모델 결과",profit:"이 모델의 순이익",loss:"이 모델의 순손실",flat:"이 모델의 손익분기",tranche:"세 차례 분할 체결",trancheWeights:"20% / 30% / 50% 체결 가정",averageEntry:"수량 가중 평균 원가",freeShort:"“무료 숏”의 의미",modelOnly:"교육용 모델입니다. 세 진입이 모두 체결됐다고 가정합니다. 가격 변동은 각 포지션 원가에서 계산하며 실제 체결이나 실제 포트폴리오 성과를 주장하지 않습니다.",invalidInput:"0보다 큰 포트폴리오, −100%~100%의 유한한 가격 변동, 0%~10%의 헤지 비중, 0%~2%의 비용을 입력하세요.",more:"전략 및 모델 펼치기",less:"전략 및 모델 접기"},es:{title:"Mesa de an\xe1lisis MakeCash",introduction:"Cuatro \xe1reas editoriales conectan la estructura del mercado con el capital familiar. Estos escenarios educativos fechados usan niveles ilustrativos declarados; no son cotizaciones diarias en directo ni recomendaciones individuales.",all:"Todas las \xe1reas",search:"Buscar s\xedmbolo o tema",searchPlaceholder:"BTC, XAU, BRENT, DXY, NVDA, DeFi…",clear:"Borrar b\xfasqueda",results:"An\xe1lisis por escenarios",empty:"Ning\xfan escenario coincide con los filtros. Cambia el s\xedmbolo o muestra todas las \xe1reas.",reset:"Restablecer filtros",read:"Leer escenario completo",close:"Cerrar escenario",back:"Volver a los escenarios",missing:"Este escenario no est\xe1 disponible. Elige un an\xe1lisis publicado a continuaci\xf3n.",published:"Publicado",assumption:"Supuestos ilustrativos",thesis:"Escenarios condicionales A / B",weights:"Pesos de atenci\xf3n editorial, no probabilidades medidas.",entry:"Entrada / nivel de revisi\xf3n",target:"Objetivo / nivel de revisi\xf3n",invalidation:"Invalidaci\xf3n / revisi\xf3n de salida",dollarUnit:"USD",indexUnit:"\xcdndice normalizado",long:"Escenario alcista",short:"Escenario bajista",audit:"Consultar s\xedmbolo en la auditor\xeda",action:"Decisi\xf3n de capital",readerLabel:"Escenario anal\xedtico completo",categories:{markets:"Mercados y acciones",crypto:"Cripto y dinero inteligente",defi:"DeFi y rentabilidad en cadena",macro:"Macroeconom\xeda y geopol\xedtica"},risks:{elevated:"Riesgo elevado entre activos",high:"Riesgo de mercado alto",protocol:"Riesgo de protocolo y custodia"},strategyTitle:"Por qu\xe9 un error de pron\xf3stico no impide que una cartera cubierta capture beneficios",strategyIntro:"Un ejemplo de cartera, no una promesa de beneficio. Una cobertura puede compensar una tesis equivocada si su propio resultado es favorable. Ambas posiciones pueden perder; los costes pueden convertir un beneficio bruto en p\xe9rdida neta.",strategyExplain:["Divide una posici\xf3n principal al contado del 10% del capital en tres tramos ejecutados: 20% a 100, 30% a 98 y 50% a 96. Las unidades compradas determinan el coste conjunto, no la media simple de precios. Las \xf3rdenes sin ejecutar, los saltos y el momento de entrada alteran el resultado.","Una exposici\xf3n corta independiente compensa el largo solo si su subyacente cae lo suficiente. Los dos movimientos siguientes son independientes: configura ambos en contra para observar el riesgo de base. Este modelo nocional sin apalancamiento reserva el presupuesto de cobertura; no calcula pr\xe9stamos, financiaci\xf3n, llamadas de margen ni liquidaciones.","Un \xabcorto gratuito\xbb asigna parte del beneficio ya realizado a un presupuesto de p\xe9rdida definido. No hace que vender en corto sea gratis o seguro. El deslizamiento del stop, la financiaci\xf3n y una subida adversa ilimitada pueden superar ese presupuesto. Nunca comprometas toda la reserva familiar en una cobertura."],simulator:"Modelo interactivo de cobertura",portfolio:"Cartera del modelo, USD",legMove:"Movimiento del largo desde coste medio, %",hedgeMove:"Movimiento del subyacente de cobertura, %",hedgeSize:"Nocional de cobertura / cartera, %",slippage:"Comisi\xf3n y deslizamiento por lado, %",modelCost:"Costes totales del modelo",legResult:"Resultado del largo principal",hedgeResult:"Resultado de la cobertura corta",netResult:"Resultado neto conjunto",unhedged:"Mismo largo sin cobertura, neto",outcome:"Resultado del modelo",profit:"Beneficio neto en este modelo",loss:"P\xe9rdida neta en este modelo",flat:"Equilibrio en este modelo",tranche:"Ejecuci\xf3n en tres tramos",trancheWeights:"20% / 30% / 50% ejecutados",averageEntry:"Coste medio ponderado por unidades",freeShort:"Qu\xe9 significa \xabcorto gratuito\xbb",modelOnly:"Solo modelo educativo. Se supone que las tres entradas se ejecutan. Cada variaci\xf3n parte del coste de su propia posici\xf3n; no se afirma ninguna ejecuci\xf3n ni rentabilidad real.",invalidInput:"Introduce una cartera superior a cero, movimientos finitos entre −100% y 100%, cobertura entre 0% y 10% y costes entre 0% y 2%.",more:"Abrir estrategia y modelo",less:"Contraer estrategia y modelo"}}}}]);